local config = {
  ui_story_5063_50630101_1_dialog_content = "(Uf... Mi cabeza.)",
  ui_story_5063_50630101_2_dialog_content = "(Debo estar más cansado de lo que pensaba, para quedarme dormido de repente afuera así.)",
  ui_story_5063_50630101_3_dialog_content = "(Gracias a Dios que me desperté justo ahora. Todavía debería tener suficiente tiempo para llegar a mi próxima reunión.)",
  ui_story_5063_50630101_4_dialog_content = "¡Por favor, espera!",
  ui_story_5063_50630101_5_dialog_content = "¿Mmm?",
  ui_story_5063_50630101_6_dialog_content = "En este momento, el Salón de Justicia está en sesión cerrada. No se permite la entrada a personas no autorizadas.",
  ui_story_5063_50630101_7_dialog_content = "¿Son ustedes guardias nuevos, por casualidad?",
  ui_story_5063_50630101_8_dialog_content = "Resulta que soy el Juez Principal aquí en el Salón de Justicia.",
  ui_story_5063_50630101_9_dialog_content = "Voy a ser el anfitrión de una reunión muy importante que comenzará en breve. Por favor, permítanme pasar para que pueda comenzar los preparativos.",
  ui_story_5063_50630101_10_dialog_content = "Estás <color=#FFB400>vestido de caballero</color>, ¿y aún así tienes la audacia de hacerse pasar por el estimado Juez Principal en este sagrado lugar?",
  ui_story_5063_50630101_11_dialog_content = "Una persona con intenciones tan retorcidas, ¿cómo podemos permitir que nos engañes de esta manera?!",
  ui_story_5063_50630101_12_dialog_content = "Realmente admiro tu dedicación y sinceridad, pero ¡realmente soy el Juez Principal de Lumopolis! Si aún no me crees...",
  ui_story_5063_50630101_13_dialog_content = "No te rindes, ¿eh? ¡Parece que tendremos que detenerte para una investigación exhaustiva!",
  ui_story_5063_50630101_14_dialog_content = "¿Qué fué lo que me dijiste?",
  ui_story_5063_50630101_15_dialog_content = "¡Alto ahí!!!",
  ui_story_5063_50630102_1_dialog_content = "(¿Por qué ninguno de estos guardias me reconoce?)",
  ui_story_5063_50630102_2_dialog_content = "(También... ¿Cuándo me cambié a este uniforme de caballero? ¡No recuerdo haberlo hecho en absoluto!)",
  ui_story_5063_50630102_3_dialog_content = "¡Alto! ¡No te atrevas a correr!",
  ui_story_5063_50630102_4_dialog_content = "...",
  ui_story_5063_50630102_5_dialog_content = "Esto es malo. ¡Está a punto de irrumpir en el Salón de la Justicia!",
  ui_story_5063_50630102_6_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5063_50630102_7_dialog_content = "Muy brillante... ¿Qué es esa cosa?",
  ui_story_5063_50630102_8_dialog_content = "¡Nuestras disculpas, Juez Principal!",
  ui_story_5063_50630102_9_dialog_content = "(¿Finalmente... me reconocen?)",
  ui_story_5063_50630102_10_dialog_content = "Juez Principal, ¡le pedimos disculpas por haberle asustado! ¡Llevaremos a este astuto impostor bajo custodia de inmediato!",
  ui_story_5063_50630102_11_dialog_content = "(Los guardias... Parece que no me hablan.)",
  ui_story_5063_50630102_12_dialog_content = "Gracias a todos por su ayuda.",
  ui_story_5063_50630102_13_dialog_content = "Esta es una nueva Caballera de Justicia en el Salón de la Justicia, así que probablemente no esté familiarizada con las reglas aquí.",
  ui_story_5063_50630102_14_dialog_content = "Me aseguraré de guiarla en cómo comportarse en el Salón de Justicia. El resto de ustedes puede irse por ahora.",
  ui_story_5063_50630102_15_dialog_content = "¡Sí, juez principal!",
  ui_story_5063_50630102_16_dialog_content = "... ¿<color=#FFB400>Juez Principal</color>?!",
  ui_story_5063_50630102_17_dialog_content = "Pero solo una persona puede ser Juez Principal... ¿Qué diablos está pasando?!",
  ui_story_5063_50630102_18_dialog_content = "Entrada no autorizada al Salón de la Justicia, tienes bastante audacia.",
  ui_story_5063_50630102_19_dialog_content = "¿Perdona? Soy Irridon, el juez principal del Salón de Justicia de Lumopolis, y tengo la libertad de ir y venir como me plazca...",
  ui_story_5063_50630102_20_dialog_content = "Ahora dime, ¿qué crees que estás haciendo en mi asiento?",
  ui_story_5063_50630102_21_dialog_content = "Tener sueños es bueno, pero debes evaluar cuidadosamente si tienes la capacidad para ello.",
  ui_story_5063_50630102_22_dialog_content = "Siempre he apreciado a los jóvenes con aspiraciones, pero no a los que se pierden en ensoñaciones.",
  ui_story_5063_50630102_23_dialog_content = "Obtén una visión clara de dónde te encuentras. Si deseas continuar sirviendo al Salón de Justicia...",
  ui_story_5063_50630102_24_dialog_content = "A partir de ahora, haz lo que digo y observa cómo lo hago.",
  ui_story_5063_50630102_25_dialog_content = "\"Haz lo que digo y observa lo que hago...\" ¡Pero esa es <color=#FFB400>la frase favorita de mi padre</color>! ¿Cómo la sabes?!",
  ui_story_5063_50630102_26_dialog_content = "Soy el sucesor elegido y favorecido por tu padre, el Juez Principal Rodell.",
  ui_story_5063_50630102_27_dialog_content = "No asumas que solo porque tu padre es el Juez Principal, automáticamente te convertirás en Juez Principal algún día.",
  ui_story_5063_50630102_28_dialog_content = "En este momento, eres simplemente un nuevo y común Caballero de Justicia en el Salón de la Justicia.",
  ui_story_5063_50630102_29_dialog_content = "Soy... ¿nada más que un Caballero de Justicia?",
  ui_story_5063_50630102_30_dialog_content = "Parece que realmente te has perdido en un sueño despierto; ¿aún no te has despertado?",
  ui_story_5063_50630102_31_dialog_content = "(Un sueño... Es cierto, tuve algunos sueños extraños esta mañana, pero ahora no puedo recordar ninguno de ellos.)",
  ui_story_5063_50630102_32_dialog_content = "(¿E-Estaba soñando todo el tiempo? ¿Por qué pensé que era el Juez Principal justo ahora?",
  ui_story_5063_50630102_33_dialog_content = "(¡Esos sueños... Debieron haber sido tan realistas que pensé que eran verdad!)",
  ui_story_5063_50630102_34_dialog_content = "(Entonces mi comportamiento hacia esos guardias hace un momento... ¡En sus ojos, no era diferente de un mentiroso!)",
  ui_story_5063_50630102_35_dialog_content = "Por favor, perdone mi comportamiento poco ceremonioso, Juez Principal...",
  ui_story_5063_50630102_36_dialog_content = "Bueno, tu actitud parece sincera.",
  ui_story_5063_50630102_37_dialog_content = "Por respeto a tu padre, dejaré pasar esto hoy. Vuelve y reflexiona sobre tus comportamientos; recompénsame a través de tus acciones.",
  ui_story_5063_50630102_38_dialog_content = "Ahora, ve y cumple con tus responsabilidades.",
  ui_story_5063_50630102_39_dialog_content = "¡Gracias, Juez Principal!",
  ui_story_5063_50630102_40_dialog_content = "(No puedo creer que cometí un error tan terrible en mi primer día. Qué vergüenza.)",
  ui_story_5063_50630102_41_dialog_content = "(Gracias a Dios que el Juez Principal tuvo la amabilidad de pasar por alto mi transgresión...)",
  ui_story_5063_50630102_42_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5063_50630102_43_dialog_content = "¿Dónde está el Juez Principal?!",
  ui_story_5063_50630102_44_dialog_content = "¡Juez Principal!",
  ui_story_5063_50630102_45_dialog_content = "Creo que estás equivocado. El Juez Principal está sentado allá.",
  ui_story_5063_50630102_46_dialog_content = "Identifícate.",
  ui_story_5063_50630102_47_dialog_content = "Juez Principal, mi familia y yo hemos sido acusados injustamente, ¡y esperamos que pueda ayudarnos a buscar justicia y limpiar nuestros nombres!",
  ui_story_5063_50630102_48_dialog_content = "Entonces, ¿te declaran culpable?",
  ui_story_5063_50630102_49_dialog_content = "Cada juicio dictado por el Salón de Justicia está sancionado por el Dios de Luz, sin absolutamente ningún margen de error.",
  ui_story_5063_50630102_50_dialog_content = "Siendo culpable, te negaste a admitir tu falta y enfrentar el castigo e irrumpiste ilegalmente en el Salón de la Justicia, profanando nuestros sagrados juicios...",
  ui_story_5063_50630102_51_dialog_content = "¡Eres simplemente atroz y mereces ser castigado aún más!",
  ui_story_5063_50630102_52_dialog_content = "...",
  ui_story_5063_50630102_53_dialog_content = "¡Humph! ¡Como era de esperar, no debería haber puesto mis esperanzas en Lumopolis en primer lugar!",
  ui_story_5063_50630102_54_dialog_content = "Sentarse en el Salón de la Justicia y darse aires no significa que realmente encarnes la justicia absoluta.",
  ui_story_5063_50630102_55_dialog_content = "Ya verás. Haré justicia a mi manera.",
  ui_story_5063_50630102_56_dialog_content = "¡Esto es escandaloso!!!",
  ui_story_5063_50630102_57_dialog_content = "Caballero de Justicia, ¿por qué sigues ahí parado?",
  ui_story_5063_50630102_58_dialog_content = "Caballero de Justicia Irridon, ¡a tus órdenes!",
  ui_story_5063_50630102_59_dialog_content = "¡Ve y arresta a la loca! ¡No me decepciones de nuevo!",
  ui_story_5063_50630102_60_dialog_content = "¡Sí, juez principal!",
  ui_story_5063_50630201_1_dialog_content = "¡Espera, detente ahí mismo!",
  ui_story_5063_50630201_2_dialog_content = "Ríndete ahora y podrías tener la oportunidad de una sentencia más leve.",
  ui_story_5063_50630201_3_dialog_content = "¿Ah? Entonces dime, ¿qué crimen he cometido realmente y por qué me estás arrestando?",
  ui_story_5063_50630201_4_dialog_content = "Al irrumpir en el Salón de la Justicia, has interrumpido el proceso judicial y violado la santidad del Salón. Esta es tu primera ofensa.",
  ui_story_5063_50630201_5_dialog_content = "Tu segundo, como tú mismo señalaste amablemente, es que eres un fugitivo de la ley.",
  ui_story_5063_50630201_6_dialog_content = "Por orden de la Juez Principal, quedas arrestado. ¡La seguridad y el cumplimiento de las leyes de Lumopolis deben ser respetados!",
  ui_story_5063_50630201_7_dialog_content = "Je, todo este hablar sobre \"seguridad\" y \"leyes\", ¡pero ni siquiera comprendes la mitad de ello!",
  ui_story_5063_50630201_8_dialog_content = "Nunca siquiera has pensado en por qué deberías obedecer esos llamados comandos...",
  ui_story_5063_50630201_9_dialog_content = "Al final del día, ¡solo eres un verdugo alimentado por esta ciudad aparentemente prístina!",
  ui_story_5063_50630201_10_dialog_content = "Debes estar realmente loco para insultar a un Caballero de la Justicia de esta manera...!",
  ui_story_5063_50630201_11_dialog_content = "¿Qué más puedo hacer? De todos modos, no escucharías. Ni siquiera me conoces, pero ya estás lleno de prejuicios...",
  ui_story_5063_50630201_12_dialog_content = "La ciudad no es mejor. Hmph, aunque solía ser parte de ella...",
  ui_story_5063_50630201_13_dialog_content = "Cuando el cuchillo no está en tu garganta, ¡nunca sabrás lo que es ser llevado a un callejón sin salida por prejuicios y arrogancia!",
  ui_story_5063_50630201_14_dialog_content = "¿Estás dispuesto a decirme qué te pasó?",
  ui_story_5063_50630201_15_dialog_content = "Qué mal, ya es demasiado tarde. Je, mira, ya están aquí.",
  ui_story_5063_50630201_16_dialog_content = "¡Protección! ¡Lealtad! ¡Gloria!",
  ui_story_5063_50630201_17_dialog_content = "¿Estás aquí para ayudarme a arrestar al fugitivo? Si es así, llegas justo a tiempo—",
  ui_story_5063_50630201_18_dialog_content = "¡Ataque!",
  ui_story_5063_50630201_19_dialog_content = "*Tose* ¿Q-Qué eres tú...?",
  ui_story_5063_50630302_1_dialog_content = "¿Qué está pasando? ¿Por qué desaparecieron esos guardias cuando fueron atacados? Estoy tan confundido...",
  ui_story_5063_50630302_2_dialog_content = "Esa mujer de la túnica negra también desapareció rápidamente. ¿A dónde pudo haber ido?",
  ui_story_5063_50630302_3_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5063_50630302_4_dialog_content = "¡Urgh! M-Mis disculpas!",
  ui_story_5063_50630302_5_dialog_content = "Corría tan rápido que no te noté ahí... ¿Estás bien?",
  ui_story_5063_50630302_6_dialog_content = "Oh...",
  ui_story_5063_50630302_7_dialog_content = "E-Estoy bien. Por favor, no te culpes, dama caballero.",
  ui_story_5063_50630302_8_dialog_content = "También tenía prisa y no me di cuenta de mi entorno...",
  ui_story_5063_50630302_9_dialog_content = "¡Si acaso, debería ser yo quien se disculpe!",
  ui_story_5063_50630302_10_dialog_content = "Por favor, no. Fui yo quien chocó contigo, no al revés.",
  ui_story_5063_50630302_11_dialog_content = "¿Te lastimaste en algún momento?",
  ui_story_5063_50630302_12_dialog_content = "Deberías que un médico te examine, solo para estar seguro. Y yo personalmente cubriré todos los gastos médicos.",
  ui_story_5063_50630302_13_dialog_content = "Fue solo un golpe y una caída, dama caballero... Aprecio tu generosidad, pero molestar a un médico por esto parece un poco innecesario.",
  ui_story_5063_50630302_14_dialog_content = "Además, ¿tienes asuntos más urgentes que atender, verdad? Me sentiría terrible si mi propia tontería interrumpiera tus nobles deberes.",
  ui_story_5063_50630302_15_dialog_content = "... Al menos déjame ayudarte a ponerte de pie.",
  ui_story_5063_50630302_16_dialog_content = "Tú también dejaste caer un par de cosas. ¿Estás seguro de que tienes todo?",
  ui_story_5063_50630302_17_dialog_content = "Sí, Dama Caballero. No parece que falte nada.",
  ui_story_5063_50630302_18_dialog_content = "Entendido. Si comienzas a sentirte mal, por favor ven a verme de inmediato. Mi nombre es Irridon Novek.",
  ui_story_5063_50630302_19_dialog_content = "Oh, antes de que se me olvide, ¿viste a un personaje sospechoso corriendo por aquí hace un momento?",
  ui_story_5063_50630302_20_dialog_content = "¿Un personaje sospechoso? N-No, no creo que sí...",
  ui_story_5063_50630302_21_dialog_content = "¿Mmm? Perdóneme, señorita, pero... ¿pasa algo?",
  ui_story_5063_50630302_22_dialog_content = "No tengas miedo. Como compañero graduado de la Dawn Academia, podría ser capaz de ayudarte.",
  ui_story_5063_50630302_23_dialog_content = "¿En serio? Gr-Gracias a la Luz... Todavía soy solo una monja en formación. Puedes llamarme <color=#FFB400>Pam</color>.",
  ui_story_5063_50630302_24_dialog_content = "La razón por la que tenía tanta prisa es—",
  ui_story_5063_50630302_25_dialog_content = "¡La encontramos, Señora Nodirri! ¡Está aquí!",
  ui_story_5063_50630302_26_dialog_content = "Ahí estás, Pam.",
  ui_story_5063_50630302_27_dialog_content = "Nuestro profesor nos pidió que recuperáramos el <color=#FFB400>Dawn Emblema</color> que tienes en tu poder. May ¿Podrías devolvérnoslo, por favor?",
  ui_story_5063_50630302_28_dialog_content = "Yo... No lo creo, no.",
  ui_story_5063_50630302_29_dialog_content = "¿Eh? Eso... Eso apenas es tu decisión para tomar.",
  ui_story_5063_50630302_30_dialog_content = "Aunque la academia te confió ese emblema para este semestre, en realidad no te pertenece. Dawn Los emblemas están destinados a ser compartidos entre los estudiantes.",
  ui_story_5063_50630302_31_dialog_content = "Teniendo en cuenta que este es el último día del semestre, no tienes más opción que devolverlo. De lo contrario... ¿Cómo le explicaré esto a nuestro profesor?",
  ui_story_5063_50630302_32_dialog_content = "¿Por qué no puedes simplemente devolverlo?",
  ui_story_5063_50630302_33_dialog_content = "Si te gusta tanto, gánatelo de vuelta el próximo semestre.",
  ui_story_5063_50630302_34_dialog_content = "Al menos podrías explicarte con nosotros, Pam.",
  ui_story_5063_50630302_35_dialog_content = "No puedo devolverlo... Porque el emblema ha sido robado.",
  ui_story_5063_50630302_36_dialog_content = "¿Qué? ¿Pero cómo? ¿Cómo pudiste permitir que algo tan preciado fuera robado?!",
  ui_story_5063_50630302_37_dialog_content = "Yo...",
  ui_story_5063_50630302_38_dialog_content = "¿Por qué dices que ha sido \"robado\"?",
  ui_story_5063_50630302_39_dialog_content = "¿Estás intentando ocultar que lo perdiste accidentalmente?",
  ui_story_5063_50630302_40_dialog_content = "¡O tal vez quieras quedártelo para ti! Digo, ese emblema es de oro sólido y vale bastante.",
  ui_story_5063_50630302_41_dialog_content = "Por favor, cálmense todos. Como Caballero de la Justicia, también fui estudiante de la Dawn Academia.",
  ui_story_5063_50630302_42_dialog_content = "Si realmente se robó el Dawn Emblema de Pam, ¡entonces esto es un asunto criminal digno de investigación!",
  ui_story_5063_50630302_43_dialog_content = "Tenga la seguridad, Pam, no descansaré hasta que el culpable sea capturado y llevado ante la justicia.",
  ui_story_5063_50630302_44_dialog_content = "La verdad es que hay alguien a quien sospecho que lo robó...",
  ui_story_5063_50630302_45_dialog_content = "Es una de mis compañeras de clase. Para evitar armar un escándalo, quería confrontarla en privado.",
  ui_story_5063_50630302_46_dialog_content = "¿Quién sabe si realmente existe tal persona? ¿Cómo sabemos si no te lo estás inventando todo?",
  ui_story_5063_50630302_47_dialog_content = "Tienes un punto... Pam está toda tartamudeando como si estuviera escondiendo algo.",
  ui_story_5063_50630302_48_dialog_content = "Si realmente hay alguien sospechoso, solo dilo y todos te ayudaremos a recuperarlo.",
  ui_story_5063_50630302_49_dialog_content = "Yo...",
  ui_story_5063_50630302_50_dialog_content = "No tengas miedo, Pam. Cuéntanos y recuperaremos el Dawn Emblema y demostraremos tu inocencia.",
  ui_story_5063_50630302_51_dialog_content = "De hecho... encontré algo cerca del lugar donde desapareció mi emblema. Era un pañuelo que pertenecía a uno de mis compañeros de clase.",
  ui_story_5063_50630302_52_dialog_content = "¿Ah? ¿Por qué me miras?",
  ui_story_5063_50630302_53_dialog_content = "Porque el pañuelo te pertenece, Nodirri.",
  ui_story_5063_50630302_54_dialog_content = "¿Me estás acusando de algo?",
  ui_story_5063_50630302_55_dialog_content = "De hecho, perdí ese pañuelo hace unos días... Además, ¡no es como si no hubiera tenido el emblema antes!",
  ui_story_5063_50630302_56_dialog_content = "Solo personas pobres encontrarían valor en robar un emblema de oro macizo como ese.",
  ui_story_5063_50630302_57_dialog_content = "Como un noble de Lumopolis, ¿por qué me rebajaría a algo tan vergonzoso como el robo? Mi familia ya tiene más que suficiente riqueza.",
  ui_story_5063_50630302_58_dialog_content = "También lo encuentro extraño, pero...",
  ui_story_5063_50630302_59_dialog_content = "¿Podría ser que me equivoque?",
  ui_story_5063_50630302_60_dialog_content = "Pam... Nunca te consideré este tipo de villana. Claramente estás desviando la culpa de ti misma, ¿verdad?",
  ui_story_5063_50630302_61_dialog_content = "¡No lo estoy! Noche Blanca en lo alto, juro que cada palabra que he dicho es la verdad. Si estoy mintiendo, ¡que el Dios de la Luz me derribe aquí mismo!",
  ui_story_5063_50630302_62_dialog_content = "¿Te acuerdas de lo que pasó antes y después de que desapareció tu emblema?",
  ui_story_5063_50630302_63_dialog_content = "Sí, estaba en la sala de estudio cuando lo quité de mi vestido. Planeaba devolvérselo a mi profesor.",
  ui_story_5063_50630302_64_dialog_content = "Pero de repente, escuché a un gatito llorar de dolor desde afuera de la ventana. Salí y busqué por todas partes, pero no pude encontrarlo.",
  ui_story_5063_50630302_65_dialog_content = "Cuando regresé a la habitación, mi Dawn Emblema había desaparecido. Lo único que encontré fue ese pañuelo...",
  ui_story_5063_50630302_66_dialog_content = "Ya veo. Por favor, déjame la investigación a mí entonces.",
  ui_story_5063_50630303_1_dialog_content = "<color=#e8d9bb>En el césped verde de la Dawn Academia, algo brilla intensamente.</color>",
  ui_story_5063_50630303_2_dialog_content = "<color=#e8d9bb>Irridon cuidadosamente aparta el follaje y descubre una pluma dorada.</color>",
  ui_story_5063_50630303_3_dialog_content = "¿Una <color=#FFB400>pluma</color>?",
  ui_story_5063_50630303_4_dialog_content = "Es de aquel entonces...",
  ui_story_5063_50630303_5_dialog_content = "Entonces, ¿qué quería la alta y poderosa Irridon contigo justo ahora?",
  ui_story_5063_50630303_6_dialog_content = "Dijo que me vio en apuros sin un bolígrafo, así que me prestó su pluma dorada.",
  ui_story_5063_50630303_7_dialog_content = "Es solo una pluma dorada, y todos tienen una. ¿Qué hay para presumir?",
  ui_story_5063_50630303_8_dialog_content = "Exactamente. ¿Y recuerdas cómo camina con esa cara indiferente, actuando como si fuera superior y altiva?",
  ui_story_5063_50630303_9_dialog_content = "Solo tiene estas calificaciones gracias a <color=#FFB400>su padre</color>. De todos modos, ¿no te parece asqueroso usar sus cosas?",
  ui_story_5063_50630303_10_dialog_content = "Por eso lo tiré hace mucho tiempo...",
  ui_story_5063_50630303_11_dialog_content = "Bien hecho.",
  ui_story_5063_50630303_12_dialog_content = "Nunca pensé que lo encontraría de nuevo después de todos estos años.",
  ui_story_5063_50630303_13_dialog_content = "Espera... ¿Realmente ha pasado tanto tiempo? ¿Por qué no puedo recordar?",
  ui_story_5063_50630303_14_dialog_content = "Tal vez sea mejor olvidar, después de todo.",
  ui_story_5063_50630304_1_dialog_content = "¿Mmm? Este informe de calificaciones es casi perfecto... Esto es algo raro, incluso en la Dawn Academia.",
  ui_story_5063_50630304_2_dialog_content = "¿Quién podría haber olvidado algo tan importante en el patio de la academia? Apenas puedo distinguir el nombre en ello...",
  ui_story_5063_50630304_3_dialog_content = "¿\"<color=#FFB400>Irridon Novek</color>\"? Espera... ¡Esto es mío!",
  ui_story_5063_50630304_4_dialog_content = "...",
  ui_story_5063_50630304_5_dialog_content = "Al principio, pensé que esto haría feliz a mi padre.",
  ui_story_5063_50630304_6_dialog_content = "Pero cuando se lo mostré, su expresión no cambió en absoluto.",
  ui_story_5063_50630304_7_dialog_content = "Para él, esto era algo que se suponía que debía lograr. Me dijo que no le hiciera perder el tiempo.",
  ui_story_5063_50630304_8_dialog_content = "Ya estaba preparado para ese tipo de respuesta... Pero ese día, dejó su trabajo solo para criticarme.",
  ui_story_5063_50630304_9_dialog_content = "Me preguntó por qué no tenía amigos en la Dawn Academia y por qué no había mantenido una mejor posición entre mis compañeros.",
  ui_story_5063_50630304_10_dialog_content = "Mi padre creía que no estaba dando lo mejor de mí y que mis acciones mancharían el buen nombre de nuestra familia. Estaba preocupado de que su trabajo se viera afectado...",
  ui_story_5063_50630304_11_dialog_content = "No sabía qué decir. Lo único que pude hacer fue bajar la cabeza avergonzado.",
  ui_story_5063_50630304_12_dialog_content = "\"¡Inútil!\"... Durante mucho tiempo después, esta fue la forma más común en que mi padre se dirigía a mí.",
  ui_story_5063_50630304_13_dialog_content = "¿Soy realmente inútil...?",
  ui_story_5063_50630304_14_dialog_content = "¿Acaso no di lo mejor de mí...?",
  ui_story_5063_50630601_1_dialog_content = "¿Cómo va la investigación, Caballero de Justicia?",
  ui_story_5063_50630601_2_dialog_content = "Pareces ser un nuevo recluta de todos modos... Me disgusta presionarte así, pero el tiempo se está acabando.",
  ui_story_5063_50630601_3_dialog_content = "Quizás debería informar de esto a nuestros profesores y dejar que la academia se encargue del asunto, ¿no?",
  ui_story_5063_50630601_4_dialog_content = "No será necesario. Ya he avanzado bastante, pero aún tengo una última pregunta para ti. Dime, ¿cuándo exactamente perdiste tu pañuelo?",
  ui_story_5063_50630601_5_dialog_content = "¿No he respondido ya a esa pregunta? Te lo dije antes, lo perdí hace unos días.",
  ui_story_5063_50630601_6_dialog_content = "El guardia de la academia te vio abrir la puerta de la sala de estudio con tu pañuelo antes. ¿Te gustaría explicar?",
  ui_story_5063_50630601_7_dialog_content = "Pensé que estaba dormido todo el tiempo...",
  ui_story_5063_50630601_8_dialog_content = "¿Así que admites que entraste a la sala de estudio hoy más temprano?",
  ui_story_5063_50630601_9_dialog_content = "Espera... Huelo algo sospechoso. Has estado del lado de Pam desde el principio, ¿verdad? Dime, ¿qué tipo de trato has hecho con ella?",
  ui_story_5063_50630601_10_dialog_content = "¡Ni siquiera te molestaste en buscarle el objeto perdido cuando todos estaban presentes!",
  ui_story_5063_50630601_11_dialog_content = "Pero yo... Solo pedí ayuda a la dama caballero porque no podía encontrar mi Dawn Emblema!",
  ui_story_5063_50630601_12_dialog_content = "Dices eso, pero ¿cómo sabemos que no estás mintiendo?",
  ui_story_5063_50630601_13_dialog_content = "¡N-no tengo nada que ocultar! ¡Regístrame, si es necesario!",
  ui_story_5063_50630601_14_dialog_content = "Como desees.",
  ui_story_5063_50630601_15_dialog_content = "Todos, por si acaso, vamos a adelantarnos y buscar.",
  ui_story_5063_50630601_16_dialog_content = "¡Y no olvides la bolsa de Pam!",
  ui_story_5063_50630601_17_dialog_content = "Encontré algo... ¿Qué es esto?!",
  ui_story_5063_50630601_18_dialog_content = "¿Un emblema Dawn?",
  ui_story_5063_50630601_19_dialog_content = "¡Así que lo tenías contigo todo el tiempo!",
  ui_story_5063_50630601_20_dialog_content = "Mentiroso desvergonzado... ¿Realmente este emblema significa tanto para ti?",
  ui_story_5063_50630601_21_dialog_content = "N-No... ¿Cómo puede ser? No estaba en mi mochila cuando la revisé...",
  ui_story_5063_50630601_22_dialog_content = "¿Qué pudo haberte obligado a hacer algo así? Cuéntanos, y podríamos estar dispuestos a entenderlo.",
  ui_story_5063_50630601_23_dialog_content = "Presidente Nodirri, no simpatice con ella. ¡Ya ha violado las leyes de Lumopolis!",
  ui_story_5063_50630601_24_dialog_content = "Caballero de la Justicia, ¿qué estás esperando? ¡Arréstala ya!",
  ui_story_5063_50630601_25_dialog_content = "El caso aún está bajo investigación.",
  ui_story_5063_50630601_26_dialog_content = "¿Qué?",
  ui_story_5063_50630601_27_dialog_content = "Este emblema Dawn no está hecho de oro sólido... De hecho, parece ser una <color=#FFB400>falsificación</color>.",
  ui_story_5063_50630601_28_dialog_content = "Dama Irridon... Esto no es una falsificación en absoluto. Puedo asegurarle que este es el emblema que perdí.",
  ui_story_5063_50630601_29_dialog_content = "¡No creas que no podemos ver a través de tu farsa! ¡Plantaste esta falsificación en tu mochila para poder mantener oculta la verdadera, ¿verdad?!",
  ui_story_5063_50630601_30_dialog_content = "¡Estás equivocado! El emblema dorado es tan precioso que me preocupaba no cuidarlo lo suficientemente bien...",
  ui_story_5063_50630601_31_dialog_content = "Así que solicité un Dawn Emblema diferente de la Academia, uno que no estuviera hecho de oro real.",
  ui_story_5063_50630601_32_dialog_content = "Sé que este emblema prácticamente no tiene valor, pero el honor que me brinda es más que suficiente.",
  ui_story_5063_50630601_33_dialog_content = "¡Ahora estás inventando cosas! ¡Nunca he oído que la Dawn Academia proporcione emblemas falsos a sus estudiantes!",
  ui_story_5063_50630601_34_dialog_content = "¡Pero no lo estoy! Solo pregúntale a nuestro maestro... ¡Verás que digo la verdad si lo haces!",
  ui_story_5063_50630601_35_dialog_content = "Si este emblema realmente no tiene valor monetario, entonces Pam no tendría motivo para robarlo.",
  ui_story_5063_50630601_36_dialog_content = "Presidente Nodirri, ¿vamos a preguntarle al profesor cómo manejar esto?",
  ui_story_5063_50630601_37_dialog_content = "¡Eso es suficiente, todos ustedes!",
  ui_story_5063_50630601_38_dialog_content = "Si el dinero no es su motivo, entonces solo puede ser una cosa... ¡Es calumnia! ¡Ha estado intentando empañar mi reputación desde el principio!",
  ui_story_5063_50630601_39_dialog_content = "¡Sin mí en el panorama, Pam no tendría problemas para ganarse un lugar en el Templo de Lumopolis como monja en formación! ¿No es cierto?!",
  ui_story_5063_50630601_40_dialog_content = "¡E-Eso no es en absoluto...!",
  ui_story_5063_50630601_41_dialog_content = "Fuiste tonta al hacer esto, Pam. Tus acciones solo te han alejado más y más del templo y su gloria.",
  ui_story_5063_50630601_42_dialog_content = "Además, alguien de tu humilde estatus no tiene derecho a ascender al Templo de Lumopolis.",
  ui_story_5063_50630601_43_dialog_content = "¡Y aunque lograras entrar, los otros nobles y sus hijos te pisotearían hasta convertirte en polvo! ¿Realmente eres tan ingenuo?!",
  ui_story_5063_50630601_44_dialog_content = "Algo no cuadra. Cuando me encontré accidentalmente con Pam antes, el contenido de su mochila estaba esparcido por el suelo.",
  ui_story_5063_50630601_45_dialog_content = "No recuerdo haber visto este emblema entre sus pertenencias caídas, ¿cómo apareció de la nada?",
  ui_story_5063_50630601_46_dialog_content = "A menos que... ¿Alguien lo puso en mi mochila después de nuestro encuentro?",
  ui_story_5063_50630601_47_dialog_content = "Es una cosa jugar una broma tan infantil con los demás, pero ¿involucrar a un Caballero de la Justicia de Lumopolis en el asunto? ¿No tienen vergüenza?!",
  ui_story_5063_50630601_48_dialog_content = "Quienquiera que sea responsable de esto debe confesar de inmediato, o no mostraré ninguna indulgencia.",
  ui_story_5063_50630601_49_dialog_content = "¡Dama Irridon!",
  ui_story_5063_50630601_50_dialog_content = "Mi Emblema Dawn está de vuelta en mi posesión y no parece estar dañado de ninguna manera. Eso es más que suficiente para tranquilizarme.",
  ui_story_5063_50630601_51_dialog_content = "Está bien, pero el asunto se ha vuelto más complicado que eso.",
  ui_story_5063_50630601_52_dialog_content = "Pero... Pero es posible que simplemente no lo haya notado antes, ¿no es cierto?",
  ui_story_5063_50630601_53_dialog_content = "Hmph, parece ser el caso. Deberías tener más cuidado la próxima vez, para no desperdiciar el tiempo de todos con tus travesuras infantiles de nuevo. ¡Vamos, todos!",
  ui_story_5063_50630601_54_dialog_content = "¿Y bien? ¿Vienes o no?!",
  ui_story_5063_50630601_55_dialog_content = "Sí, Presidente Nodirri.",
  ui_story_5063_50630601_56_dialog_content = "¿Por qué decidiste dejarla ir, Pam? ¡Ella era claramente la culpable!",
  ui_story_5063_50630601_57_dialog_content = "Porque ella no cometió nada verdaderamente atroz... Fue solo un lapso momentáneo de escrúpulos, nada más. Además, estoy seguro de que su corazón ya está lleno de culpa y remordimiento.",
  ui_story_5063_50630601_58_dialog_content = "El Dios de la Luz nos enseña a ser comprensivos. Como monja en formación, no tengo derecho a ir en contra de nuestras enseñanzas.",
  ui_story_5063_50630601_59_dialog_content = "Creo que el Dios de la Luz guiará sus pasos y la ayudará a ser una mejor persona... Noche Blanca en lo alto.",
  ui_story_5063_50630601_60_dialog_content = "¿En serio? Je, muy bien entonces. Incluso si este incidente nunca hubiera ocurrido, estoy seguro de que el Templo de Lumopolis te habría elegido para quedarte.",
  ui_story_5063_50630601_61_dialog_content = "¿Eh? Ellos aún no han tomado su decisión, sabes...",
  ui_story_5063_50630601_62_dialog_content = "Ojalá hubiera tenido un compañero de clase como tú cuando estaba en la Academia. Tal vez... podríamos haber sido amigos.",
  ui_story_5063_50630601_63_dialog_content = "Pero eres una caballera tan valiente y dedicada, Lady Irridon! Estoy seguro de que tenías muchos amigos en la Academia!",
  ui_story_5063_50630601_64_dialog_content = "Todo lo contrario, en realidad. Todos pensaban que mis logros eran simplemente el resultado de ser la hija de mi padre. Decir que era detestada por mis compañeros sería quedarse corto.",
  ui_story_5063_50630601_65_dialog_content = "Incluso mi padre comenzó a creer los rumores que difundían sobre mí. Fue... Un momento muy solitario en mi pasado.",
  ui_story_5063_50630601_66_dialog_content = "¡Entonces seamos amigos ahora!",
  ui_story_5063_50630601_67_dialog_content = "Aunque no seamos compañeros de clase, ¡podemos ser grandes amigos! ¡Nuestro encuentro debe haber sido planeado perfectamente por el destino!",
  ui_story_5063_50630601_68_dialog_content = "¿Planeado... por el destino?",
  ui_story_5063_50630601_69_dialog_content = "¡Por supuesto! ¿Quién más podría haberme rescatado sino la Dama Irridon de los Caballeros de la Justicia?",
  ui_story_5063_50630601_70_dialog_content = "B-Bueno, hay muchos otros caballeros—",
  ui_story_5063_50630601_71_dialog_content = "No es un delito reconocer tus propios talentos y valor, Lady Irridon. ¿No estás de acuerdo?",
  ui_story_5063_50630601_72_dialog_content = "¿Eh? N-No, supongo que no es ilegal...",
  ui_story_5063_50630601_73_dialog_content = "Ahora que lo pienso, creo que Pittman también quiere convertirse en un Caballero de la Justicia.",
  ui_story_5063_50630601_74_dialog_content = "<color=#FFB400>Pittman</color>? Ese nombre me suena un poco familiar...",
  ui_story_5063_50630601_75_dialog_content = "Él es uno de mis amigos. Estaría absolutamente emocionado de conocer a un Caballero de Justicia tan excepcional como tú, ¡sabes!",
  ui_story_5063_50630601_76_dialog_content = "¿Crees que soy... excepcional?",
  ui_story_5063_50630601_77_dialog_content = "¡Por supuesto! Me aseguraré de presentarlos algún día.",
  ui_story_5063_50630601_78_dialog_content = "¡Ay, mira la hora! Todavía necesito visitar a mi abuelo en su casa...",
  ui_story_5063_50630601_79_dialog_content = "Perdóname, Lady Irridon, ¡pero debo irme ahora!",
  ui_story_5063_50630601_80_dialog_content = "La próxima vez que nos encontremos, ¡te prometo recompensarte adecuadamente por todo lo que has hecho!",
  ui_story_5063_50630701_1_dialog_content = "¿Soy... realmente un Caballero de Justicia excepcional?",
  ui_story_5063_50630701_2_dialog_content = "¿Qué tipo de Caballero de Justicia deja ir a un criminal...",
  ui_story_5063_50630701_3_dialog_content = "¿Debería informar de esto al Juez Principal?",
  ui_story_5063_50630701_4_dialog_content = "¡Ve y arresta a la loca! ¡No me decepciones de nuevo!",
  ui_story_5063_50630701_5_dialog_content = "Solo la decepcionaría aún más de lo que ya lo he hecho...",
  ui_story_5063_50630701_6_dialog_content = "Probablemente ella piensa que soy inútil, igual que mi padre.",
  ui_story_5063_50630701_7_dialog_content = "De hecho... Podrían echarme del Salón de la Justicia por esto...",
  ui_story_5063_50630701_8_dialog_content = "...",
  ui_story_5063_50630701_9_dialog_content = "¿Eh? ¡¡Es ella!!",
  ui_story_5063_50630701_10_dialog_content = "Está intentando escapar al Patio Lumopolis desde la Escalera a los Cielos...",
  ui_story_5063_50630701_11_dialog_content = "¡Bueno, al menos los Jardines de Lumopolis están a salvo de sus acciones!",
  ui_story_5063_50630701_12_dialog_content = "¡Espera, eso no es motivo de alivio! ¡Tengo que atraparla!",
  ui_story_5063_50630701_13_dialog_content = "¡Protección! ¡Lealtad! ¡Gloria!",
  ui_story_5063_50630701_14_dialog_content = "¡Esos soldados extraños están de vuelta otra vez!",
  ui_story_5063_50630701_15_dialog_content = "¡Por favor, no te interpongas en mi camino! ¡Estás obstaculizando mi persecución de un criminal!",
  ui_story_5063_50630802_1_dialog_content = "Detener-!",
  ui_story_5063_50630802_2_dialog_content = "¿Desapareció de nuevo? Debería preguntarle a la gente más adelante si la vieron.",
  ui_story_5063_50630802_3_dialog_content = "¡Siempre podemos ir al Salón de Justicia si es necesario!",
  ui_story_5063_50630802_4_dialog_content = "Mis pensamientos exactamente. ¡Juro que llegaré al fondo de esto!",
  ui_story_5063_50630802_5_dialog_content = "Perdónenme, buenos señores, pero ¿alguno de ustedes notó a una mujer sospechosa vestida de negro corriendo por esta zona?",
  ui_story_5063_50630802_6_dialog_content = "No he visto a una mujer de negro, pero este hombre frente a nosotros, Jerry, me parece muy sospechoso.",
  ui_story_5063_50630802_7_dialog_content = "¡Esta es tu oportunidad, Señor Alcalde! ¡Adelante, comparte tus pensamientos con el Salón de Justicia!",
  ui_story_5063_50630802_8_dialog_content = "Abordar a personas inocentes en la calle, solo para interrogarlas ciegamente... ¿También es esto parte de la educación de la nobleza?!",
  ui_story_5063_50630802_9_dialog_content = "¡Conoce tu lugar, siervo! La educación de los nobles apenas concierne a un humilde campesino como tú.",
  ui_story_5063_50630802_10_dialog_content = "Las alteraciones públicas son una violación directa de la ley de Lumopolis. Les sugiero a los dos que se calmen de inmediato.",
  ui_story_5063_50630802_11_dialog_content = "¿Ahora cuál parece ser el problema? Estaría más que feliz de mediar.",
  ui_story_5063_50630802_12_dialog_content = "Eres un Caballero de Justicia, ¿verdad? Por favor, perdona mi arrebato de hace un momento.",
  ui_story_5063_50630802_13_dialog_content = "Llegaste en el momento justo. Me gustaría presentar un informe en contra de este sirviente descaradamente codicioso. Me ayudarás, ¿verdad?",
  ui_story_5063_50630802_14_dialog_content = "De nuevo, por favor cálmate y dime exactamente qué ha pasado.",
  ui_story_5063_50630802_15_dialog_content = "Hoy, mi anciano padre falleció <color=#FFB400>repentina y misteriosamente</color>.",
  ui_story_5063_50630802_16_dialog_content = "Llegué a encargarme de su propiedad tan pronto como recibí la noticia, pero este hombre aquí, un sirviente al servicio de mi padre llamado Jerry, se niega a dejarme entrar al lugar.",
  ui_story_5063_50630802_17_dialog_content = "Me presentó este extraño <color=#FFB400>testamento</color>, diciendo que mi padre le legó su título y propiedad completamente a él.",
  ui_story_5063_50630802_18_dialog_content = "La idea misma de un padre privando a su propio hijo del nombre y estatus de su familia...",
  ui_story_5063_50630802_19_dialog_content = "S-Si esto fuera cierto, ¡nuestra familia sería reducida a la plebe común!",
  ui_story_5063_50630802_20_dialog_content = "Es absolutamente absurdo, ¿no te parece? Como caballero, ¡seguro que estás de acuerdo!",
  ui_story_5063_50630802_21_dialog_content = "A menos que haya juego sucio, es realmente muy poco común que un noble renuncie a todo su legado, especialmente a...",
  ui_story_5063_50630802_22_dialog_content = "¿A un humilde sirviente? Eso es lo que ibas a decir, ¿verdad?",
  ui_story_5063_50630802_23_dialog_content = "¿Tengo razón al suponer que naciste en una vida de riqueza y nobleza, dama caballero? ¿Una vida en la que todos tus deseos y necesidades se satisfacen con un chasquido de dedos?",
  ui_story_5063_50630802_24_dialog_content = "Independientemente de mi origen, soy un Caballero de la Justicia de Lumopolis y tengo el deber de tratar a ambas partes de manera justa y equitativa.",
  ui_story_5063_50630802_25_dialog_content = "Ahora por favor, comparte tu versión del asunto.",
  ui_story_5063_50630802_26_dialog_content = "Aunque es cierto que el Señor Mayor es hijo de mi amo, siempre han estado en desacuerdo el uno con el otro, y el Señor Mayor rara vez visitaba a mi amo cuando estaba vivo.",
  ui_story_5063_50630802_27_dialog_content = "Hasta el momento en que dio su último aliento, fui yo quien cuidó de mi maestro, día y noche.",
  ui_story_5063_50630802_28_dialog_content = "A pesar de mi humilde origen, mi maestro siempre me animó a mejorar. Con el tiempo, comenzó a considerarme como a su propio hijo.",
  ui_story_5063_50630802_29_dialog_content = "Redactó este testamento para demostrar su sinceridad y disipar mis dudas. Verás que está completamente de acuerdo con la ley de Lumopolis...",
  ui_story_5063_50630802_30_dialog_content = "¡No he dicho más que la verdad! Si algo de lo que he dicho es mentira, ¡que el Dios de la Luz me castigue!",
  ui_story_5063_50630802_31_dialog_content = "No se deje engañar por su lenguaje florido, dama caballero. El Dios de la Luz nunca escucharía ni una sola palabra de su boca mentirosa.",
  ui_story_5063_50630802_32_dialog_content = "En cuanto a mis pocas visitas, mi padre me dejó pocas opciones. El hombre simplemente se negaba a verme.",
  ui_story_5063_50630802_33_dialog_content = "Y antes de que comiences a sospechar algo, nunca le hice nada malo a mi padre. Siempre fue muy estricto conmigo y sus expectativas siempre fueron muy altas...",
  ui_story_5063_50630802_34_dialog_content = "En sus ojos, yo no era más que un hijo indolente, ignorante y complaciente.",
  ui_story_5063_50630802_35_dialog_content = "A pesar de mis mejores esfuerzos por cumplir con sus exigencias, nunca estuvo satisfecho. Ni una sola vez me reconoció como una persona valiosa.",
  ui_story_5063_50630802_36_dialog_content = "A pesar de su insatisfacción conmigo, sé que mi padre nunca habría dejado un testamento así.",
  ui_story_5063_50630802_37_dialog_content = "Y eso es porque él quería mucho a su nieta, mi propia hija.",
  ui_story_5063_50630802_38_dialog_content = "Ella lo visitaba a menudo para hacerle compañía y asegurarse de que estuviera bien. Negarme a mí es una cosa, ¡pero él nunca privaría a su nieta de su legítima herencia!",
  ui_story_5063_50630802_39_dialog_content = "¿También conoces a la nieta de tu maestro, Jerry?",
  ui_story_5063_50630802_40_dialog_content = "Sí. También tenía curiosidad de por qué mi maestro no le dejó su fortuna, pero él dijo que ella tenía poco necesidad de ello.",
  ui_story_5063_50630802_41_dialog_content = "¡Jajajaja! ¡Qué completamente ridículo! Me atrevo a decir que nunca he escuchado una mentira más patética en toda mi vida.",
  ui_story_5063_50630802_42_dialog_content = "¡Admítelo! ¡Todo esto es solo un vil plan para robarnos nuestros medios de vida!",
  ui_story_5063_50630802_43_dialog_content = "Lord Mayor, ya deberías saber que no soy un hombre motivado por la riqueza. Si lo fuera, nunca me habría quedado al lado de tu padre durante tanto tiempo.",
  ui_story_5063_50630802_44_dialog_content = "Sin embargo, mi maestro me dejó muy claro que estos son sus últimos deseos, ¡y no tengo intención de deshonrarlos!",
  ui_story_5063_50630802_45_dialog_content = "(Siento que he visto un dilema similar antes. ¿Fue un caso de mis días en la academia?)",
  ui_story_5063_50630802_46_dialog_content = "(No puedo recordar... Ugh, ¿por qué me siento tan mareado?)",
  ui_story_5063_50630802_47_dialog_content = "¿Dama Irridon?",
  ui_story_5063_50630802_48_dialog_content = "Padre, Jerry... ¿Qué están haciendo todos aquí? ¿Se conocen entre ustedes?",
  ui_story_5063_50630802_49_dialog_content = "¿Conoces a este caballero, Pam?",
  ui_story_5063_50630802_50_dialog_content = "Sí, papá. La Lady Irridon es una amiga mía que recientemente me ayudó con un problema. De hecho, estaba considerando invitarla a cenar...",
  ui_story_5063_50630802_51_dialog_content = "Eso no será un problema, ¿verdad, padre? Después de todo, ustedes dos ya parecen conocerse.",
  ui_story_5063_50630802_52_dialog_content = "Ahora, si todos me disculpan, estoy preocupado por mi abuelo. Nadie respondió la puerta cuando fui a visitarlo hace un momento... ¿Alguien sabe por qué?",
  ui_story_5063_50630802_53_dialog_content = "Pam, tu abuelo... Ya no está con nosotros.",
  ui_story_5063_50630802_54_dialog_content = "<size=45>¿É-Él falleció?!</size>",
  ui_story_5063_50630802_55_dialog_content = "¡Pero abuelo siempre fue tan saludable! ¿¡Cómo pudo haber pasado esto?! ¡No lo creo! ¡Esto debe ser algún tipo de broma!",
  ui_story_5063_50630802_56_dialog_content = "Todavía no ha visto mi aceptación formal en el Templo de Lumopolis, ¿cómo podría dejarme así?",
  ui_story_5063_50630802_57_dialog_content = "¿Padre? ¿Jerry? ¿Por qué tienen esas expresiones en sus rostros? Por favor... Díganme que esto no es real...",
  ui_story_5063_50630802_58_dialog_content = "(No puedo permitirme ignorar este caso, especialmente porque afecta a Pam tan profundamente.)",
  ui_story_5063_50630802_59_dialog_content = "A todos, por favor acepten mis más sinceras condolencias...",
  ui_story_5063_50630802_60_dialog_content = "Permítame encargarme personalmente de la investigación de este asunto.",
  ui_story_5063_50630803_1_dialog_content = "<color=#e8d9bb>Durante la investigación de Irridon en la casa del abuelo de Pam, encuentra inesperadamente una vara de señalar escondida en un rincón, aparentemente discreta.</color>",
  ui_story_5063_50630803_2_dialog_content = "Un <color=#FFB400>palillo indicador</color>...",
  ui_story_5063_50630803_3_dialog_content = "¡Es exactamente igual que el de mi padre!",
  ui_story_5063_50630803_4_dialog_content = "Mis manos aún recuerdan el dolor de cada error que cometí.",
  ui_story_5063_50630803_5_dialog_content = "Ese dolor frío, duro y punzante...",
  ui_story_5063_50630803_6_dialog_content = "Solo ver uno de estos palos apuntadores es suficiente para acelerar mi corazón.",
  ui_story_5063_50630803_7_dialog_content = "De repente, recuerdo esa terrible escena: mi padre de pie frente a mí, con las garras de un Eclipsite hundiéndose profundamente en su pecho...",
  ui_story_5063_50630803_8_dialog_content = "Mi padre nunca se preocupó por mí, entonces, ¿por qué sacrificaría su vida por su \"inútil\" hija?",
  ui_story_5063_50630803_9_dialog_content = "Todavía no entiendo. Por eso, incluso ahora, todavía tengo demasiado miedo para pasar por su estudio...",
  ui_story_5063_50630803_10_dialog_content = "Una vez que deje de ser tan inútil y me convierta en un Caballero de la Justicia digno a los ojos del Juez Principal... ¿Tendré el valor de enfrentarme a mi padre entonces?",
  ui_story_5063_50630803_11_dialog_content = "El padre de Pam, Lord Major, parece compartir una historia similar con su propio padre.",
  ui_story_5063_50630803_12_dialog_content = "Pero por el bien de su hija, logró poner fin a este ciclo vicioso en su propio tiempo. Dudo que haya sido fácil para él.",
  ui_story_5063_50630803_13_dialog_content = "Señor Mayor... Lo has hecho bien.",
  ui_story_5063_50630803_14_dialog_content = "En cuanto a mí... necesito hacer lo mismo.",
  ui_story_5063_50630804_1_dialog_content = "¿Es ese un archivo oficial de caso tirado al lado del camino? ¿Qué tipo de torpe descuidado podría haber...",
  ui_story_5063_50630804_2_dialog_content = "¡Espera! ¿Es este el archivo del caso para mi investigación actual?!",
  ui_story_5063_50630804_3_dialog_content = "Parece que el juez que preside este caso encontró que el testamento es de naturaleza dudosa...",
  ui_story_5063_50630804_4_dialog_content = "La razón es que... El testigo presente en la firma del testamento era un sirviente, no un notario oficial. Por lo tanto, el testimonio del testigo no pudo ser aceptado legalmente.",
  ui_story_5063_50630804_5_dialog_content = "Con el testamento declarado inválido, la distribución de la propiedad del fallecido quedó bajo la jurisdicción de nuestras leyes comunes de herencia.",
  ui_story_5063_50630804_6_dialog_content = "¿Pero cómo podría ser eso? ¡Necesito encontrar al juez que supervisó este caso y enfrentarme a ellos sobre esto!",
  ui_story_5063_50630804_7_dialog_content = "Hay una firma en la parte inferior...",
  ui_story_5063_50630804_8_dialog_content = "\"¿<color=#FFB400>Rodell Novek</color>\"?!",
  ui_story_5063_50630804_9_dialog_content = "¿Mi <color=#FFB400>padre</color> presidió este caso?!",
  ui_story_5063_50630804_10_dialog_content = "¿Eso significa que tengo que dar el mismo veredicto que él...?",
  ui_story_5063_50630804_11_dialog_content = "¿Es realmente la única forma de ganar su aceptación? ¿Aceptando y obedeciendo cada una de sus palabras?",
  ui_story_5063_50630804_12_dialog_content = "De alguna manera...",
  ui_story_5063_50630804_13_dialog_content = "De alguna manera, no creo que este haya sido el veredicto correcto...",
  ui_story_5063_50631101_1_dialog_content = "(Aunque las razones aún no están claras, parece que el abuelo de Pam realmente se quitó la vida. Entonces, el punto de controversia se centra en su testamento.)",
  ui_story_5063_50631101_2_dialog_content = "(En forma y contenido, este testamento fue escrito en perfecta conformidad con las leyes de herencia de Lumopolis.)",
  ui_story_5063_50631101_3_dialog_content = "(La única discrepancia es que el testigo no era un noble, sino un anciano sirviente... Sin embargo, eso difícilmente es una razón válida para negar la autenticidad de un testamento.)",
  ui_story_5063_50631101_4_dialog_content = "(Pero si el testamento es aceptado por el tribunal, Pam y su familia perderán su estatus de nobles. ¿No afectaría eso también a su futuro?)",
  ui_story_5063_50631101_5_dialog_content = "(No quiero arriesgar nuestra amistad por esto... ¿Qué debo hacer?)",
  ui_story_5063_50631101_6_dialog_content = "Dama Irridon? No estoy entrometiendo, ¿verdad?",
  ui_story_5063_50631101_7_dialog_content = "¡Por favor, no malinterpretes! Simplemente quiero decirte... ¡Por favor, no permitas que nuestro conocimiento se interponga en el camino de emitir un juicio justo!",
  ui_story_5063_50631101_8_dialog_content = "Noche Blanca en lo alto. Como Caballero de la Justicia de Lumopolis, has sido elegido por el Dios de la Luz para servir al pueblo de esta ciudad de manera igualitaria y sin prejuicios.",
  ui_story_5063_50631101_9_dialog_content = "Perdóneme si sueno presuntuoso, pero por favor... ¡No permita que nuestra amistad empañe la santidad del juicio justo!",
  ui_story_5063_50631101_10_dialog_content = "Pam...",
  ui_story_5063_50631101_11_dialog_content = "Mi padre me enseñó hace mucho tiempo que un verdadero servidor de la justicia es imparcial.",
  ui_story_5063_50631101_12_dialog_content = "Tengan la seguridad de que reuniré las pruebas necesarias para emitir un juicio justo y honesto.",
  ui_story_5063_50631101_13_dialog_content = "¿Ya ha llegado a una conclusión, dama caballero?",
  ui_story_5063_50631101_14_dialog_content = "¡También espero ansiosamente su juicio, milady!",
  ui_story_5063_50631101_15_dialog_content = "Finalmente he llegado a un veredicto, sí.",
  ui_story_5063_50631101_16_dialog_content = "¡Noche Blanca en lo alto! De acuerdo con las leyes de Lumopolis sobre herencias y testamentos finales, por la presente declaro que este testamento es legalmente válido.",
  ui_story_5063_50631101_17_dialog_content = "¡Pero el testigo no era más que un simple sirviente! Seguramente notaste tal violación flagrante, ¿verdad?!",
  ui_story_5063_50631101_18_dialog_content = "Tu juicio imprudente sacudirá a toda Lumopolis hasta sus mismos cimientos!",
  ui_story_5063_50631101_19_dialog_content = "No hay ninguna ley en Lumopolis que prohíba a una persona actuar como testigo basándose únicamente en su situación económica. Esto es simplemente un rumor que existe entre los miembros de la nobleza.",
  ui_story_5063_50631101_20_dialog_content = "Siempre que una persona sea honesta, diligente y no tenga antecedentes legales, tiene todo el derecho de ser un testigo confiable.",
  ui_story_5063_50631101_21_dialog_content = "¿Tú... Y te llamas a ti mismo un Caballero de Justicia de Lumopolis?!",
  ui_story_5063_50631101_22_dialog_content = "¡Papá, detente! Cuando un grupo de estudiantes nobles me acusó de robar un Emblema Dawn de la Academia, fue Lady Irridon quien descubrió la verdad detrás de sus acciones!",
  ui_story_5063_50631101_23_dialog_content = "Nuestro prejuicio hacia el Sr. Jerry no es diferente al prejuicio que esos otros nobles mostraron hacia nosotros.",
  ui_story_5063_50631101_24_dialog_content = "En cualquier caso, confío en Lady Irridon y su capacidad para emitir un juicio justo y razonable.",
  ui_story_5063_50631101_25_dialog_content = "Tú tampoco, Pam...",
  ui_story_5063_50631101_26_dialog_content = "Si realmente este fue el último deseo de abuelo, no nos queda más opción que honrarlo.",
  ui_story_5063_50631101_27_dialog_content = "Suspiro, ¿cómo terminaron las cosas así? Y aquí pensé que podría darte un poco más...",
  ui_story_5063_50631101_28_dialog_content = "Quizás el anciano nunca quiso un hijo como yo, después de todo.",
  ui_story_5063_50631101_29_dialog_content = "¡Eso no es cierto en absoluto, padre! Sé que siempre ha habido una gran distancia entre tú y yo...",
  ui_story_5063_50631101_30_dialog_content = "Pero el abuelo nunca se quejó ni habló mal de ti cuando lo visité. También tenías tu propia forma silenciosa de cuidarlo, ¿verdad?",
  ui_story_5063_50631101_31_dialog_content = "Si ambos hubieran dado ese primer paso el uno hacia el otro, ¡estoy seguro de que podrían haber cerrado la brecha entre ustedes!",
  ui_story_5063_50631101_32_dialog_content = "Padre...",
  ui_story_5063_50631101_33_dialog_content = "(¿Mi padre y yo tenemos una distancia similar e intransitable entre nosotros?)",
  ui_story_5063_50631101_34_dialog_content = "(Aunque las cosas estén como están ahora, mi veredicto sigue siendo completamente diferente al de él.)",
  ui_story_5063_50631101_35_dialog_content = "(¿Será que... mi juicio sigue siendo afectado por mis emociones?!)",
  ui_story_5063_50631101_36_dialog_content = "(No fue mi amistad con Pam, sino mi deseo de rebelarme contra mi padre... ¡Eso fue lo que me impulsó a emitir este veredicto!)",
  ui_story_5063_50631101_37_dialog_content = "¿Por qué te has quedado tan callada, Dama Irridon? Si es por nuestra difícil situación... Entonces te pido humildemente que te abstengas de compadecernos.",
  ui_story_5063_50631101_38_dialog_content = "No es nada, solo me recordó a mi propio padre. Si él todavía estuviera con nosotros hoy... ¿Habría emitido un veredicto diferente?",
  ui_story_5063_50631101_39_dialog_content = "Ya veo. ¿Esto significa que deseas ser más como tu padre, Dama Irridon?",
  ui_story_5063_50631101_40_dialog_content = "¡Nunca!",
  ui_story_5063_50631101_41_dialog_content = "Perdóname si me expresé mal, pero ¿realmente estás tan en contra de la idea?",
  ui_story_5063_50631101_42_dialog_content = "De lo contrario, ¿por qué te preocuparía tanto el juicio de tu padre?",
  ui_story_5063_50631101_43_dialog_content = "Yo...",
  ui_story_5063_50631101_44_dialog_content = "Tienes razón. ¿Por qué me preocupa tanto el veredicto al que llegaría mi padre? ¿Y por qué me convertí en Caballero de Justicia en primer lugar?",
  ui_story_5063_50631101_45_dialog_content = "<size=45>¡Esto es todo! ¡Aprehender a todos en esta casa!</size>",
  ui_story_5063_50631101_46_dialog_content = "<size=45>¡Sí!</size>",
  ui_story_5063_50631101_47_dialog_content = "¡¿E-Eh?!",
  ui_story_5063_50631101_48_dialog_content = "¡Pam! ¡Suélten a mi hija, brutos!",
  ui_story_5063_50631101_49_dialog_content = "¿Esto realmente está pasando? El testamento que escribió mi maestro... ¿Ha sido aceptado por el tribunal?",
  ui_story_5063_50631101_50_dialog_content = "¿Por qué están deteniendo a esta familia? ¿De quién son las órdenes que siguen?",
  ui_story_5063_50631101_51_dialog_content = "Los miembros de la casa Pyrrhus ignoraron las advertencias y estaban investigando los cristales rojos. El Señor de la Ciudad y el Juez Principal han emitido órdenes de arresto para todos los miembros de la familia.",
  ui_story_5063_50631101_52_dialog_content = "¡Estas son las sentencias y órdenes de arresto! Personas no involucradas, salgan inmediatamente, ¡o los arrestaremos a todos!",
  ui_story_5063_50631101_53_dialog_content = "¡E-Espera! ¡No soy parte de esta familia!",
  ui_story_5063_50631101_54_dialog_content = "Ya sea que estés involucrado o no, investigaremos a fondo. ¡Ahora, sigue adelante!",
  ui_story_5063_50631101_55_dialog_content = "Pam...",
  ui_story_5063_50631101_56_dialog_content = "Perdóname, Lady Irridon... Quería invitarte a cenar con mi familia, pero parece que tendremos que reprogramar.",
  ui_story_5063_50631101_57_dialog_content = "¡Mantente fuerte! ¡Encontraré una forma de salvarte!",
  ui_story_5063_50631101_58_dialog_content = "Ya has hecho mucho por mí, así que por favor no te molestes más por mi bien... Solo pesaría aún más en mi corazón.",
  ui_story_5063_50631101_59_dialog_content = "Incluso yo sé que investigar los cristales rojos está estrictamente prohibido. Aunque mis padres y yo no hemos cometido ningún delito...",
  ui_story_5063_50631101_60_dialog_content = "Cuando uno de los nuestros es declarado culpable, toda nuestra familia carga con el peso de sus pecados.",
  ui_story_5063_50631101_61_dialog_content = "Pero no te preocupes. Tomaré esto como una oportunidad para mostrar al Dios de la Luz mi arrepentimiento y devoción, y seguiré esforzándome para convertirme en una monja del Templo de Lumopolis.",
  ui_story_5063_50631101_62_dialog_content = "Si ese día llega, estoy seguro de que también serás un juez completamente calificado del Salón de Justicia.",
  ui_story_5063_50631101_63_dialog_content = "¡Haré... haré mi mejor esfuerzo! ¡Algún día me convertiré en un juez puro y justo!",
  ui_story_5063_50631101_64_dialog_content = "¡Muévete! ¡No hay tiempo para charlas!",
  ui_story_5063_50631101_65_dialog_content = "¡Hasta el próximo encuentro, amigo!",
  ui_story_5063_50631101_66_dialog_content = "Adiós...",
  ui_story_5063_50631103_1_dialog_content = "¿Es este otro de los veredictos de mi padre?",
  ui_story_5063_50631103_2_dialog_content = "No... Este es un informe de investigación privado escrito por mi propio padre.",
  ui_story_5063_50631103_3_dialog_content = "\"Antes de fallecer, el difunto barón descubrió que toda su familia sería arrestada pronto.\"",
  ui_story_5063_50631103_4_dialog_content = "\"Temeroso de que su hijo y nieta fueran implicados, ideó un último plan desesperado.\"",
  ui_story_5063_50631103_5_dialog_content = "\"Al otorgar su título y propiedad a su sirviente más cercano en su testamento, el difunto barón creía que su familia sería perdonada.\"",
  ui_story_5063_50631103_6_dialog_content = "¿Qué...? ¿Cómo y cuándo descubrió mi padre esos detalles tan impactantes?",
  ui_story_5063_50631103_7_dialog_content = "Incluso si era para proteger a su familia, el abuelo de Pam no tenía derecho a involucrar a su inocente sirviente.",
  ui_story_5063_50631103_8_dialog_content = "<size=45>¡¡¡!!!</size>",
  ui_story_5063_50631103_9_dialog_content = "Entonces mi padre estaba al tanto de las intenciones del barón todo el tiempo. ¿Es por eso que decidió anular su testamento?",
  ui_story_5063_50631103_10_dialog_content = "Como era de esperar... el veredicto de padre fue correcto, después de todo...",
  ui_story_5063_50631103_11_dialog_content = "¿Q-Qué he hecho...?",
  ui_story_5063_50631201_1_dialog_content = "He buscado en todo el Patio de Lumopolis, pero aún no hay señales de la mujer de negro. ¿Podría haber escapado a la Baja Lumopolis?",
  ui_story_5063_50631201_2_dialog_content = "Nunca hice muchos viajes a Baja Lumopolis en el pasado... Incluso el ambiente es completamente diferente de las partes superiores de la ciudad.",
  ui_story_5063_50631201_3_dialog_content = "Siento innumerables ojos observándome mientras camino por las calles... ¿Es realmente tan fuera de lugar la presencia de un Caballero de la Justicia aquí?",
  ui_story_5063_50631201_4_dialog_content = "¿Qué haces aquí, Caballero de Justicia?",
  ui_story_5063_50631201_5_dialog_content = "¿J-Juez Principal?!",
  ui_story_5063_50631201_6_dialog_content = "Yo... M-Mis disculpas, pero debido a mi propia incapacidad, aún no he atrapado a la mujer de negro.",
  ui_story_5063_50631201_7_dialog_content = "Pero durante mi búsqueda, logré resolver varios casos no relacionados para algunos de los residentes locales...",
  ui_story_5063_50631201_8_dialog_content = "¿La mujer de negro? ¿Qué mujer de negro?",
  ui_story_5063_50631201_9_dialog_content = "¿Eh? La persona que irrumpió en el Salón de Justicia y solicitó que limpiaras su nombre...",
  ui_story_5063_50631201_10_dialog_content = "Hmm... ahora que lo mencionas, sí recuerdo vagamente a esa persona.",
  ui_story_5063_50631201_11_dialog_content = "Pero podemos dejar eso en espera por ahora. Tengo una tarea más importante para ti.",
  ui_story_5063_50631201_12_dialog_content = "Tenemos información que sugiere que Mirren Gautier podría estar involucrado en traición. Investiga si esta pista tiene algo de verdad.",
  ui_story_5063_50631201_13_dialog_content = "A-¿Estás seguro de que deseas dejarme a cargo de una tarea tan importante?",
  ui_story_5063_50631201_14_dialog_content = "Eh, quiero decir... ¡Gracias por depositar su confianza en mí, Juez Principal! Comenzaré mi investigación sobre la presunta traición de Mirren Gautier de inmediato...",
  ui_story_5063_50631201_15_dialog_content = "Espera... ¿Alguien planea rebelarse contra la ciudad?!",
  ui_story_5063_50631201_16_dialog_content = "Esta tarea concierne a la supervivencia de Lumopolis, lo que significa que debe llevarse a cabo sin errores, sin margen para equivocaciones. ¿Entiendes?",
  ui_story_5063_50631201_17_dialog_content = "¡Sí, juez principal!",
  ui_story_5063_50631201_18_dialog_content = "¡No permitiré que nadie profane la ciudad que juré proteger!",
  ui_story_5063_50631201_19_dialog_content = "Tampoco permitiré decepcionarte, Juez Principal...",
  ui_story_5063_50631201_20_dialog_content = "¡Protección! ¡Lealtad! ¡Gloria!",
  ui_story_5063_50631201_21_dialog_content = "No otra vez... ¿De dónde siguen saliendo?!",
  ui_story_5063_50631201_22_dialog_content = "¡Por favor, retírese a un lugar seguro, Juez Principal! ¡Yo puedo lidiar con ellos!",
  ui_story_5063_50631201_23_dialog_content = "¡Ataque!",
  ui_story_5063_50631302_1_dialog_content = "(El Juez Jefe dijo que ella no podía ver a esos extraños guardias...)",
  ui_story_5063_50631302_2_dialog_content = "(¿Podría ser que solo yo puedo verlos?)",
  ui_story_5063_50631302_3_dialog_content = "¿Me engañan los ojos... Eres tú, Dama Irridon?",
  ui_story_5063_50631302_4_dialog_content = "¡¿Pam?!",
  ui_story_5063_50631302_5_dialog_content = "¡Noche Blanca en lo alto! ¡Realmente eres tú! Pero, ¿qué haces en Lumopolis Bajo?",
  ui_story_5063_50631302_6_dialog_content = "Pensé que no te vería de nuevo por mucho más tiempo...",
  ui_story_5063_50631302_7_dialog_content = "Tengo un trabajo que hacer aquí abajo. ¿Has estado... bien?",
  ui_story_5063_50631302_8_dialog_content = "¡Sí! Como puedes ver, mi cuerpo y espíritu están en perfecta salud.",
  ui_story_5063_50631302_9_dialog_content = "Escuché que a toda tu familia le quitaron sus Luminatics...",
  ui_story_5063_50631302_10_dialog_content = "Esto... era de esperarse. Después de todo, nuestra familia fue responsable de cometer un pecado imperdonable.",
  ui_story_5063_50631302_11_dialog_content = "Por la ley de Lumopolis, nuestro castigo es completamente adecuado.",
  ui_story_5063_50631302_12_dialog_content = "...E-En cualquier caso, ¡veo todo esto como una experiencia completamente nueva! Después de todo, nunca había estado en la Baja Lumopolis antes de nuestro exilio.",
  ui_story_5063_50631302_13_dialog_content = "¡Mientras nuestra familia permanezca unida, podemos sobrevivir en cualquier lugar!",
  ui_story_5063_50631302_14_dialog_content = "Pero, ¿qué pasa con el período de prueba del Templo de Lumopolis...?",
  ui_story_5063_50631302_15_dialog_content = "Bueno, es cierto que ya no tengo forma de regresar...",
  ui_story_5063_50631302_16_dialog_content = "Pero incluso así, mi fe se mantiene firme. Rezo al Dios de la Luz todos los días para obtener absolución, tal como siempre lo he hecho en el pasado.",
  ui_story_5063_50631302_17_dialog_content = "Mientras persevero, estoy seguro de que habrá un lugar para mí en el Templo de Lumopolis en algún momento del futuro.",
  ui_story_5063_50631302_18_dialog_content = "Tu puro optimismo me deja sin palabras...",
  ui_story_5063_50631302_19_dialog_content = "A diferencia de ti, estoy lleno de dudas y aprensión, tanto que ni siquiera puedo completar las tareas que tengo ante mí.",
  ui_story_5063_50631302_20_dialog_content = "No necesitas compararte con los demás, ¿sabes? Cada persona es única y tiene sus propios problemas que resolver en la vida.",
  ui_story_5063_50631302_21_dialog_content = "En mis ojos, Dama Irridon, ya eres una persona sobresaliente y trabajadora. ¿Estás seguro de que no esperas demasiado de ti mismo?",
  ui_story_5063_50631302_22_dialog_content = "¿Tú... de verdad lo crees?",
  ui_story_5063_50631302_23_dialog_content = "Vaya... ¿Por qué de repente soy yo el que está siendo consolado?",
  ui_story_5063_50631302_24_dialog_content = "...Pero basta de eso. Si tú o tu familia tienen algún problema, ¡debes decírmelo de inmediato!",
  ui_story_5063_50631302_25_dialog_content = "¡Jajaja! Aprecio mucho su preocupación, Lady Irridon!",
  ui_story_5063_50631302_26_dialog_content = "¿Oh? ¿Ya es hora del almuerzo? Si aún no has comido, ¿te gustaría unirte a nosotros?",
  ui_story_5063_50631302_27_dialog_content = "Si no es mucha molestia, entonces sí...",
  ui_story_5063_50631302_28_dialog_content = "Después de todo, esta es... La primera vez que un amigo me ha invitado a comer juntos. ¡Sería un honor acompañarte!",
  ui_story_5063_50631302_29_dialog_content = "¡La comida estará lista en solo unos minutos!",
  ui_story_5063_50631302_30_dialog_content = "Desde que nos conocimos, he querido invitarte a cenar con mi familia...",
  ui_story_5063_50631302_31_dialog_content = "Comencé a pensar que nunca estaba destinado a ser... Pero luego el destino nos volvió a unir, ¡aquí en Baja Lumopolis!",
  ui_story_5063_50631302_32_dialog_content = "Sé que no es la cena y no hay muchos platos para elegir...",
  ui_story_5063_50631302_33_dialog_content = "Pero a través del estudio y la práctica, ¡he aprendido a preparar comidas decentes con los escasos ingredientes disponibles aquí!",
  ui_story_5063_50631302_34_dialog_content = "Sí, y me tienes que agradecer por las habilidades culinarias que heredaste, Pam. ¡Jajaja!",
  ui_story_5063_50631302_35_dialog_content = "¡Solo estoy agradecido de no haber heredado también tu fanfarronería, papá!",
  ui_story_5063_50631302_36_dialog_content = "P-Pam! ¿Cómo puedes ridiculizar a tu pobre padre frente a Lady Irridon?!",
  ui_story_5063_50631302_37_dialog_content = "Jejeje, ¡solo estoy bromeando! Después de todo, mamá te lo hace todo el tiempo, ¿verdad?",
  ui_story_5063_50631302_38_dialog_content = "Debe perdonar a mi hija por su comportamiento tonto, Lady Irridon. Por favor, sírvase usted mismo.",
  ui_story_5063_50631302_39_dialog_content = "Te puedo asegurar que no probarás algo así en los Jardines de Lumopolis. ¡Jajajaja!",
  ui_story_5063_50631302_40_dialog_content = "Sé que no parece especialmente extravagante, pero...",
  ui_story_5063_50631302_41_dialog_content = "Munch...",
  ui_story_5063_50631302_42_dialog_content = "¿Bien? ¿Se ajusta a tus gustos?",
  ui_story_5063_50631302_43_dialog_content = "<size=45>¡¡¡!!!</size>",
  ui_story_5063_50631302_44_dialog_content = "...Es tan delicioso.",
  ui_story_5063_50631302_45_dialog_content = "De hecho, ¡mi cuerpo está lleno de energía renovada después de probarlo!",
  ui_story_5063_50631302_46_dialog_content = "Nunca supe que un tazón de sopa podría hacerme sentir tan increíble...",
  ui_story_5063_50631302_47_dialog_content = "No le agregaste una poción de Lumina, ¿verdad Pam?",
  ui_story_5063_50631302_48_dialog_content = "Y ¿dónde diablos encontraría el dinero para un ingrediente tan caro, Dama Irridon?",
  ui_story_5063_50631302_49_dialog_content = "No, si acaso... Lo que estás saboreando solo podría describirse como <color=#FFB400>el amor de una familia</color>.",
  ui_story_5063_50631302_50_dialog_content = "\"El amor de una familia...\"",
  ui_story_5063_50631302_51_dialog_content = "De nuevo, debe disculpar a mi hija, Lady Irridon. Su forma de hablar puede ser un poco confusa a veces.",
  ui_story_5063_50631302_52_dialog_content = "Por el contrario, estoy muy agradecido con Pam por compartir sus pensamientos conmigo.",
  ui_story_5063_50631302_53_dialog_content = "No solo eso, sino que creo que también te debo una disculpa con respecto al testamento de tu padre...",
  ui_story_5063_50631302_54_dialog_content = "No es necesario, mi señora. Todo está en el pasado ahora y hace tiempo que lo acepté.",
  ui_story_5063_50631302_55_dialog_content = "Cuando llegamos a la Baja Lumopolis, no éramos diferentes a los plebeyos que antes veíamos con tanto desprecio. Al principio, pensé que nuestras vidas estarían llenas de miseria y sufrimiento.",
  ui_story_5063_50631302_56_dialog_content = "Pero como plebeyos, pronto descubrí que las personas a nuestro alrededor eran mucho mejores ayudando y cuidándose mutuamente que cualquier aristócrata que haya conocido.",
  ui_story_5063_50631302_57_dialog_content = "En Lumopolis, los nobles a menudo deben pisotear a la gente que está debajo de ellos para mantener sus posiciones.",
  ui_story_5063_50631302_58_dialog_content = "La única forma de evitarlo es empujando a otros hacia abajo y pisoteándolos, en su lugar.",
  ui_story_5063_50631302_59_dialog_content = "Al final del día, ¿cuál sería el punto de volver a una vida tan explotadora?",
  ui_story_5063_50631302_60_dialog_content = "Mi único lamento es que Pam perdió su oportunidad de unirse al Templo de Lumopolis...",
  ui_story_5063_50631302_61_dialog_content = "Pero como una rama de la familia Pyrrhus, nunca fuiste directamente responsable de ninguno de sus crímenes.",
  ui_story_5063_50631302_62_dialog_content = "No solo eso, sino que no puedo pensar en alguien más digna de convertirse en monja que Pam. Su devoción y personalidad me lo demuestran.",
  ui_story_5063_50631302_63_dialog_content = "Cuando termine con mi tarea actual, me aseguraré de informar de esto a la Jueza Principal. ¡Quizás ella permita que regrese al Templo de Lumopolis!",
  ui_story_5063_50631303_1_dialog_content = "\"La familia Pyrrhus, en conjunto con la familia Gautier, utilizó Eclipsites aumentados para llevar a cabo una violenta rebelión...\"",
  ui_story_5063_50631303_2_dialog_content = "\"Cada miembro de sus respectivas familias ha sido condenado a muerte. En caso de más resistencia, serán ejecutados en el acto.\"",
  ui_story_5063_50631303_3_dialog_content = "¿E-Esto es otro de los veredictos de mi padre...?",
  ui_story_5063_50631303_4_dialog_content = "¡Pero esto es completamente contrario a los resultados de mi investigación!",
  ui_story_5063_50631303_5_dialog_content = "Es cierto que ambas familias fueron exiliadas a la Baja Lumopolis como resultado de la investigación de la familia Pyrrhus sobre los cristales rojos...",
  ui_story_5063_50631303_6_dialog_content = "¡Pero ahora mismo, los que están conspirando con los Eclipsites para perseguir a la familia Pyrrhus no son otros que Mirren Gautier y sus parientes!",
  ui_story_5063_50631303_7_dialog_content = "Seguro que mi papá no pudo haber pasado por alto un detalle tan importante...",
  ui_story_5063_50631303_8_dialog_content = "Entonces, ¿por qué juzgaría de esta manera?",
  ui_story_5063_50631303_9_dialog_content = "Este caso afecta a todo Lumopolis y su seguridad... ¿Estoy realmente lo suficientemente seguro de mi propio juicio como para anular el veredicto de mi padre?",
  ui_story_5063_50631303_10_dialog_content = "¿Podría ser...? ¿Descubrió algo más?",
  ui_story_5063_50631303_11_dialog_content = "De todos modos, ¡no hay motivo para seguir persiguiendo a una familia inocente por esto!",
  ui_story_5063_50631303_12_dialog_content = "Padre...",
  ui_story_5063_50631303_13_dialog_content = "Parece que la distancia entre nosotros... solo ha aumentado...",
  ui_story_5063_50631601_1_dialog_content = "...Eso concluye mi informe de investigación.",
  ui_story_5063_50631601_2_dialog_content = "Bien, ¡informaré de estos resultados de investigación al juez principal de inmediato!",
  ui_story_5063_50631601_3_dialog_content = "¡Tienes mi gratitud!",
  ui_story_5063_50631601_4_dialog_content = "Ahora bien, todavía tengo una última cosa por hacer...",
  ui_story_5063_50631601_5_dialog_content = "¿Has estado avanzando en tu misión, Dama Irridon?",
  ui_story_5063_50631601_6_dialog_content = "Eh... Sí. De hecho, el asunto está prácticamente resuelto ahora.",
  ui_story_5063_50631601_7_dialog_content = "Entonces... ¿Te irás pronto?",
  ui_story_5063_50631601_8_dialog_content = "Por favor, ¡no malinterpretes! Simplemente pensé que si no tenías prisa, podrías venir a nuestra casa y cenar con nosotros.",
  ui_story_5063_50631601_9_dialog_content = "Mamá y papá están preparando un festín en este momento!",
  ui_story_5063_50631601_10_dialog_content = "¡Ahhhh!",
  ui_story_5063_50631601_11_dialog_content = "<size=45>¡Purgar a los traidores! ¡Purgar a los traidores! ¡Purgar a los traidores!</size>",
  ui_story_5063_50631601_12_dialog_content = "¿Por qué esos guardias están arrestando a todos?!",
  ui_story_5063_50631601_13_dialog_content = "<size=45>¡Purgar a los traidores! ¡Purgar a los traidores! ¡Purgar a los traidores!</size>",
  ui_story_5063_50631601_14_dialog_content = "(Parece que el Juez Principal ya ha dado la orden de arrestar a la familia Gautier... Pero, ¿qué tiene que ver esto con la familia Pyrrhus?)",
  ui_story_5063_50631601_15_dialog_content = "(¿Podría ser que el juez principal piense que las dos familias están coludidas entre sí?)",
  ui_story_5063_50631601_16_dialog_content = "(Pero eso significaría que Pam es...)",
  ui_story_5063_50631601_17_dialog_content = "¿Eh? ¡Padre!",
  ui_story_5063_50631601_18_dialog_content = "Pam... ¡Olvídate de mí!",
  ui_story_5063_50631601_19_dialog_content = "<size=45>¡Huye, Pam! ¡Corre lo más rápido que puedas!!!</size>",
  ui_story_5063_50631601_20_dialog_content = "¿Por qué están arrestando a mi padre, Dama Irridon?!",
  ui_story_5063_50631601_21_dialog_content = "No hemos hecho más que obedecer la ley desde que llegamos a Lumopolis Bajo, entonces, ¿por qué...? Dime, Lady Irridon!",
  ui_story_5063_50631601_22_dialog_content = "¿Podría ser que esto tenga algo que ver con tu misión...?",
  ui_story_5063_50631601_23_dialog_content = "No puedo hablarte de mi tarea, Pam. Al menos no ahora... Pero puedo asegurarte que no tiene nada que ver con esto.",
  ui_story_5063_50631601_24_dialog_content = "Por ahora, solo escucha a tu padre y corre.",
  ui_story_5063_50631601_25_dialog_content = "<size=45>¡Ahora ve!</size>",
  ui_story_5063_50631601_26_dialog_content = "¿Se escapó un miembro de la familia Pyrrhus por allá?",
  ui_story_5063_50631601_27_dialog_content = "Dejen sus sospechas de lado, guardias; esa chica no pertenece a la familia Pyrrhus. Simplemente se asustó al verlos y escapó.",
  ui_story_5063_50631601_28_dialog_content = "Entiendo. ¡Vamos a buscar de nuevo por allí!",
  ui_story_5063_50631601_29_dialog_content = "Pam...",
  ui_story_5063_50631601_30_dialog_content = "Jeje, así que incluso el Caballero de Justicia es capaz de decir mentiras, ¿eh?",
  ui_story_5063_50631601_31_dialog_content = "¡Eres tú! Te he estado buscando durante un tiempo... ¡Qué amable de tu parte entregarte a mí!",
  ui_story_5063_50631601_32_dialog_content = "Tú, un Caballero de Justicia de Lumopolis, dejaste que un criminal tan importante se te escapara de las manos...",
  ui_story_5063_50631601_33_dialog_content = "¿Qué crimen crees que has cometido?",
  ui_story_5063_50631601_34_dialog_content = "Como Caballero de la Justicia, defender las leyes de Lumopolis no es mi única responsabilidad. ¡También tengo la obligación de proteger a las personas inocentes de esta ciudad!",
  ui_story_5063_50631601_35_dialog_content = "Debe haber algún tipo de malentendido. ¿Por qué si no el Juez Principal detendría a toda la familia Pyrrhus...?",
  ui_story_5063_50631601_36_dialog_content = "Voy a explicarle todo a la primera oportunidad que tenga y aclarar a Pam y su familia de cualquier falta!",
  ui_story_5063_50631601_37_dialog_content = "¿Oh? Si ese es el caso, ¿por qué me persigues tan implacablemente?",
  ui_story_5063_50631601_38_dialog_content = "Porque tú...",
  ui_story_5063_50631601_39_dialog_content = "¿Hmm?",
  ui_story_5063_50631601_40_dialog_content = "Eres...",
  ui_story_5063_50631601_41_dialog_content = "<size=45><color=#FFB400>¿Pam</color>?!*</size>",
  ui_story_5063_50631601_42_dialog_content = "Hace siglos que alguien no me llamaba por ese nombre...",
  ui_story_5063_50631601_43_dialog_content = "Pero quizás me conozcas mejor por uno de los nombres en tu lista de los más buscados: <color=#FFB400>Paloma Pyrrhus</color>.",
  ui_story_5063_50631601_44_dialog_content = "¿Me has estado mintiendo todo este tiempo...?",
  ui_story_5063_50631601_45_dialog_content = "¿Oh? Jeje, parece que lo has olvidado después de todo...",
  ui_story_5063_50631601_46_dialog_content = "¿Estás dispuesto a decirme qué te pasó?",
  ui_story_5063_50631601_47_dialog_content = "Eres tú quien me pidió que te explicara mi situación.",
  ui_story_5063_50631601_48_dialog_content = "Pero justo cuando estaba a punto de hacerlo, \"Pam\" de repente se separó de mi cuerpo.",
  ui_story_5063_50631601_49_dialog_content = "La persona que conoces como Pam soy yo, pero al mismo tiempo no soy yo...",
  ui_story_5063_50631601_50_dialog_content = "En este mismo momento, ella debe estar escondida en algún lugar y experimentando el mismo dolor que sentí hace más de una década... Pobrecita.",
  ui_story_5063_50631601_51_dialog_content = "Entonces, cuando te abriste paso en el Salón de Justicia... ¿Fue para denunciar este acto de rebelión?",
  ui_story_5063_50631601_52_dialog_content = "Debí darme cuenta antes...",
  ui_story_5063_50631601_53_dialog_content = "¡Pero aún hay tiempo! Simplemente informaré de mis hallazgos al juez principal y exoneraré a Pam... ¡Y a ti también!",
  ui_story_5063_50631601_54_dialog_content = "Tendremos que esperar y ver entonces, ¿no?",
  ui_story_5063_50631601_55_dialog_content = "¡Caballero de Justicia!",
  ui_story_5063_50631601_56_dialog_content = "La fugitiva está justo frente a tus ojos. ¿Por qué no la has arrestado ya?",
  ui_story_5063_50631601_57_dialog_content = "Antes de eso, me gustaría saber qué te impulsó a autorizar los arrestos de las familias Gautier y Pyrrhus.",
  ui_story_5063_50631601_58_dialog_content = "¿No es todo esto gracias a tu investigación?",
  ui_story_5063_50631601_59_dialog_content = "Pero mi investigación ya ha demostrado que la mayoría de los miembros de la familia Pyrrhus son víctimas en este caso, ¡no perpetradores!",
  ui_story_5063_50631601_60_dialog_content = "Ambas familias, Gautier y Pyrrhus, estuvieron involucradas en experimentos prohibidos. ¿No es cierto?",
  ui_story_5063_50631601_61_dialog_content = "Sí, pero ya han sido castigados por ese delito. Además, no puedes responsabilizar a cada persona de sus familias por eso.",
  ui_story_5063_50631601_62_dialog_content = "¡Caballero de Justicia! ¿De verdad tengo que revisar uno por uno para ver quién se convirtió en un monstruo voluntariamente por traición y quién no?",
  ui_story_5063_50631601_63_dialog_content = "Para mantener la seguridad y estabilidad de Lumopolis, no podemos permitirnos dejar ningún riesgo potencial.",
  ui_story_5063_50631601_64_dialog_content = "¿Y qué pasa con las personas inocentes que no tuvieron parte en esos experimentos?",
  ui_story_5063_50631601_65_dialog_content = "No se convirtieron en monstruos... ¡No hicieron nada en absoluto! Entonces, ¿por qué deben cargar con la culpa y perder sus vidas por ello?",
  ui_story_5063_50631601_66_dialog_content = "¿Inocentes? ¡Qué broma! La familia Pyrrhus fue culpable desde el principio. Cuando el Salón de Justicia los condenó al exilio en la Baja Lumopolis, ya fue una misericordia.",
  ui_story_5063_50631601_67_dialog_content = "Ahora, incluso se han involucrado en este caso de traición... ¿Por qué deberíamos ser indulgentes con un grupo de posibles criminales de Lower Lumopolis?",
  ui_story_5063_50631601_68_dialog_content = "¿Cómo puedes determinar si una persona merece un trato justo bajo la ley basándote únicamente en su estatus y residencia?!",
  ui_story_5063_50631601_69_dialog_content = "Todavía creo que su juicio es defectuoso, Juez Principal——",
  ui_story_5063_50631601_70_dialog_content = "¡Este es un juicio que tu padre también tomaría!",
  ui_story_5063_50631601_71_dialog_content = "Tu padre es un juez principal de Lumopolis muy respetado. ¿Qué, ahora te estás enfrentando a tu propio padre?",
  ui_story_5063_50631601_72_dialog_content = "Yo...",
  ui_story_5063_50631601_73_dialog_content = "Jeje.",
  ui_story_5063_50631601_74_dialog_content = "Entonces, ¿todavía tienes esperanza en Lumopolis y el Salón de la Justicia, veo?",
  ui_story_5063_50631601_75_dialog_content = "¡No permitas que sigan lavándote el cerebro!",
  ui_story_5063_50631601_76_dialog_content = "¡¿Qué estás haciendo?!",
  ui_story_5063_50631601_77_dialog_content = "No intentaré lastimarte, ¡pero será mejor que te mantengas al margen!",
  ui_story_5063_50631601_78_dialog_content = "¡Es hora de que erradique la fuente del mal que se esconde detrás de ti!",
  ui_story_5063_50631601_79_dialog_content = "¡Caballero de la Justicia! ¡Acaba con esta mujer loca ahora!",
  ui_story_5063_50631601_80_dialog_content = "...",
  ui_story_5063_50631601_81_dialog_content = "¡Para, Paloma!",
  ui_story_5063_50631601_82_dialog_content = "Jeje... Realmente no eres diferente a ellos.",
  ui_story_5063_50631601_83_dialog_content = "No, Paloma... ¡Simplemente me niego a verte cometer un error aún mayor!",
  ui_story_5063_50631601_84_dialog_content = "No son ustedes quienes deciden lo que está bien o mal. ¡No existe tal cosa como la justicia en Lumópolis!",
  ui_story_5063_50631601_85_dialog_content = "Matar a alguien tampoco te traerá la justicia que buscas.",
  ui_story_5063_50631601_86_dialog_content = "Si no enfrentas un problema desde su origen, ¡nunca desaparecerá! ¡Podrías destruir todo Lumopolis y aún así no detendrías el ciclo de odio y venganza!",
  ui_story_5063_50631601_87_dialog_content = "Con el tiempo, alguien más simplemente crearía un Salón de Justicia aún más arrogante y prejuiciado.",
  ui_story_5063_50631601_88_dialog_content = "Además, ¿de verdad vas a hacer esto? ¿No te molesta la nobleza por eliminar a todos los que se interponen en su camino?",
  ui_story_5063_50631601_89_dialog_content = "¿Estás intentando ser como ellos?!",
  ui_story_5063_50631601_90_dialog_content = "¡No soy nada como ellos!",
  ui_story_5063_50631601_91_dialog_content = "Entonces dime, ¿cuál es la diferencia entre tus acciones ahora y las de ellos?",
  ui_story_5063_50631601_92_dialog_content = "...",
  ui_story_5063_50631601_93_dialog_content = "En ese caso... ¿Tienes alguna idea mejor?",
  ui_story_5063_50631601_94_dialog_content = "¡Momento perfecto!",
  ui_story_5063_50631601_95_dialog_content = "¡Desmembrar!",
  ui_story_5063_50631601_96_dialog_content = "¡Urgh! Maldita sea... Debería haber esperado un ataque furtivo...",
  ui_story_5063_50631601_97_dialog_content = "Qué mal por ti... Me subestimaste...",
  ui_story_5063_50631601_98_dialog_content = "*tos* Caballero de la Justicia... arreste... a esta mujer loca... *tos*",
  ui_story_5063_50631601_99_dialog_content = "Estaré en el Salón de Justicia... esperando tu actualización...",
  ui_story_5063_50631601_100_dialog_content = "¡Jajaja! Así es, corre con tu cola... Entre tus piernas...",
  ui_story_5063_50631601_101_dialog_content = "Paloma! A-¿Estás bien?",
  ui_story_5063_50631601_102_dialog_content = "Jeje, así que finalmente me atrapaste. Ahora puedes finalmente presentarle a tu preciada Juez Principal algo que la hará feliz.",
  ui_story_5063_50631601_103_dialog_content = "¡Estás perdiendo demasiada sangre! ¡Déjame ayudarte!",
  ui_story_5063_50631601_104_dialog_content = "Hmph, realmente no tienes que seguir fingiendo, ¿sabes? Ya hemos pasado esa etapa.",
  ui_story_5063_50631601_105_dialog_content = "¡Oye! ¿No me escuchaste? ¡Deja de perder el tiempo intentando tratar mis heridas!",
  ui_story_5063_50631601_106_dialog_content = "¡Pero quiero ayudar! ¿Qué más necesitas que haga?",
  ui_story_5063_50631601_107_dialog_content = "Tch, no necesito la ayuda de nadie, así que déjalo. Todo lo que necesito es un veredicto justo... ¿Crees que puedes darme eso?",
  ui_story_5063_50631601_108_dialog_content = "¡Yo... Claro que sí puedo!",
  ui_story_5063_50631601_109_dialog_content = "¡Noche Blanca en lo alto! Tras una extensa investigación, el Salón de Justicia concluye que el Mayor Pyrrhus y su familia no albergaban intenciones rebeldes. Además, no estuvieron involucrados en los experimentos Eclipsite llevados a cabo por la familia Gautier...",
  ui_story_5063_50631601_110_dialog_content = "Por lo tanto, por la presente declaro que todos ellos... ¡No son culpables!",
  ui_story_5063_50631601_111_dialog_content = "...¿No culpable, eh?",
  ui_story_5063_50631601_112_dialog_content = "Je, debo estar soñando.",
  ui_story_5063_50631601_113_dialog_content = "Paloma? ¿Adónde vas?",
  ui_story_5063_50631601_114_dialog_content = "Si realmente estoy soñando, entonces tal vez sea hora de que finalmente despierte.",
  ui_story_5063_50631601_115_dialog_content = "En cuanto a ti...",
  ui_story_5063_50631601_116_dialog_content = "Me pregunto si alguna vez harás lo mismo?",
  ui_story_5063_50631601_117_dialog_content = "En serio... ¿Por qué querías convertirte en un Caballero de la Justicia?",
  ui_story_5063_50631701_1_dialog_content = "¿Qué es este lugar? Y... ¿A dónde voy?",
  ui_story_5063_50631701_2_dialog_content = "¿El Salón de Justicia?",
  ui_story_5063_50631701_3_dialog_content = "En serio... ¿Por qué querías convertirte en un Caballero de la Justicia?",
  ui_story_5063_50631701_4_dialog_content = "Ni siquiera puedo recordar la razón por la que quería trabajar en el Salón de Justicia en primer lugar...",
  ui_story_5063_50631701_5_dialog_content = "He fallado en cada tarea que me ha asignado el Juez Principal.",
  ui_story_5063_50631701_6_dialog_content = "Y cada veredicto que he dictado es completamente opuesto a lo que mi padre decidió.",
  ui_story_5063_50631701_7_dialog_content = "Digo que quiero cambiar Lumopolis para mejor, pero... ¿Qué puedo lograr realmente por mi cuenta?",
  ui_story_5063_50631701_8_dialog_content = "<color=#e8d9bb>Zumbido...</color>",
  ui_story_5063_50631701_9_dialog_content = "¿Eh? ¿Qué fue eso?",
  ui_story_5063_50631701_10_dialog_content = "<color=#e8d9bb>Zumbido...</color>",
  ui_story_5063_50631701_11_dialog_content = "¿Por qué mi lupa salió volando de mi bolsillo? Espera, hay algo extraño en la lente...",
  ui_story_5063_50631701_12_dialog_content = "¿Qué? ¡H-Hay una figura en la lente!",
  ui_story_5063_50631701_13_dialog_content = "Espera, esa figura... ¿Es el Juez Principal?",
  ui_story_5063_50631701_14_dialog_content = "Pero algo en la cara del Juez Principal es diferente. Se ve... ¿Un poco dorada?",
  ui_story_5063_50631701_15_dialog_content = "Eh... Tú... Te ves...",
  ui_story_5063_50631701_16_dialog_content = "¡Así es como te ves ahora!",
  ui_story_5063_50631701_17_dialog_content = "¿Quién eres...?",
  ui_story_5063_50631701_18_dialog_content = "Soy tu amigo, PlayerName!",
  ui_story_5063_50631701_19_dialog_content = "Pero eso no importa. Lo que importa es... ¡necesitas recordar quién eres!",
  ui_story_5063_50631701_20_dialog_content = "Yo... soy yo. Irridon Novek, un Caballero de Justicia de Lumopolis.",
  ui_story_5063_50631701_21_dialog_content = "¡Mira este espejo aquí! ¡Muestra tu apariencia!",
  ui_story_5063_50631701_22_dialog_content = "¿Es... mi reflejo? ¡Debe ser una broma! ¿Por qué me parecería tanto al Juez Principal?",
  ui_story_5063_50631701_23_dialog_content = "¡Porque en realidad eres el Juez Principal!",
  ui_story_5063_50631701_24_dialog_content = "¿Soy el verdadero Juez Principal? Entonces, ¿quién era esa otra mujer de antes?",
  ui_story_5063_50631701_25_dialog_content = "Ella... también es tú, pero solo una parte de ti. Es la versión idealizada de ti misma a la que aspiras ser en el mundo real...",
  ui_story_5063_50631701_26_dialog_content = "Pero ella realmente no eres tú! Porque has mezclado demasiadas ideas de otras personas en tus propias expectativas.",
  ui_story_5063_50631701_27_dialog_content = "¡Recupera tu verdadero yo!",
  ui_story_5063_50631701_28_dialog_content = "<size=45>¡Despierta ahora!</size>",
  ui_story_5063_50631701_29_dialog_content = "...",
  ui_story_5063_50631701_30_dialog_content = "¿Por qué me dices que \"despierte\"?",
  ui_story_5063_50631701_31_dialog_content = "Si realmente estoy soñando, entonces tal vez sea hora de que finalmente despierte.",
  ui_story_5063_50631701_32_dialog_content = "En cuanto a ti...",
  ui_story_5063_50631701_33_dialog_content = "Me pregunto si alguna vez harás lo mismo?",
  ui_story_5063_50631701_34_dialog_content = "Ahora que lo pienso, todo lo que he experimentado... Esas personas y sus casos... Algo parecía un poco extraño en ellos.",
  ui_story_5063_50631701_35_dialog_content = "Pero si realmente estoy soñando, ¿cómo se supone que debo despertar?",
  ui_story_5063_50631701_36_dialog_content = "...Necesito encontrarla. A la otra yo.",
  ui_story_5063_50631801_1_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5063_50631801_2_dialog_content = "¿Tú? ¿Cómo entraste aquí?",
  ui_story_5063_50631801_3_dialog_content = "El caso que involucra al criminal conocido como Paloma ha sido resuelto. Dígame, juez principal, ¿está satisfecho con mi desempeño?",
  ui_story_5063_50631801_4_dialog_content = "Has estado demasiado indeciso. Si no fuera por mi intervención, habrías cometido un error imperdonable.",
  ui_story_5063_50631801_5_dialog_content = "Si hubieras obedecido mis órdenes desde el principio, las cosas habrían sido mucho más fluidas.",
  ui_story_5063_50631801_6_dialog_content = "\"¿Más suave\"? ¿Quieres decir reemplazarme, sí?",
  ui_story_5063_50631801_7_dialog_content = "Entonces finalmente estás empezando a recordar...",
  ui_story_5063_50631801_8_dialog_content = "Ya veo... Reemplazarme siempre fue tu plan, ¿no es así?",
  ui_story_5063_50631801_9_dialog_content = "Lamentablemente, no dejaré que eso suceda, ¡ni ahora ni nunca!",
  ui_story_5063_50631801_10_dialog_content = "Es inútil resistirse más. Yo soy la hija perfecta que papá siempre quiso, no tú.",
  ui_story_5063_50631801_11_dialog_content = "¡Solo yo soy digno de ser el verdadero Juez Principal de Lumopolis!",
  ui_story_5063_50631801_12_dialog_content = "Tú, por otro lado, ¡solo has logrado ayudar y ser cómplice del mal! El sacrificio de papá se desperdicia en alguien como tú.",
  ui_story_5063_50631801_13_dialog_content = "¿Es eso realmente cierto? Gracias... Creo que entiendo un poco mejor a papá ahora.",
  ui_story_5063_50631801_14_dialog_content = "Ahora me doy cuenta de que siempre he estado ansioso por volver a revisar los casos antiguos de mi padre, para corregir sus errores así como los del Salón de Justicia...",
  ui_story_5063_50631801_15_dialog_content = "Pero en lo que más deseo emitir un juicio... No es en el juicio de venganza de Paloma.",
  ui_story_5063_50631801_16_dialog_content = "¡Pero más bien las tradiciones arrogantes y prejuiciosas de Lumopolis!",
  ui_story_5063_50631801_17_dialog_content = "¿Te escuchas siquiera en este momento? ¿Cómo puedes afirmar que los veredictos de papá estaban equivocados?!",
  ui_story_5063_50631801_18_dialog_content = "Papá emitió muchos juicios razonables en su tiempo, pero incluso él cometió errores. ¡Esos errores llevaron a veredictos injustos, que a su vez causaron la muerte de personas inocentes!",
  ui_story_5063_50631801_19_dialog_content = "Debería haber sido responsabilizado por sus errores en un tribunal, pero su muerte puso fin a cualquier investigación.",
  ui_story_5063_50631801_20_dialog_content = "Pero ahora, finalmente sé qué impidió que mi padre tomara mejores decisiones.",
  ui_story_5063_50631801_21_dialog_content = "Una enfermedad corría por sus venas, una que ha afectado a todo Lumopolis a lo largo de su larga historia...",
  ui_story_5063_50631801_22_dialog_content = "¡Una enfermedad que se esconde en lo profundo de tu subconsciente, así como en el mío!",
  ui_story_5063_50631801_23_dialog_content = "¡Es orgullo! El orgullo está en el corazón de la corrupción de Lumópolis, ¡y al juzgarlo, lo purgaré de mi propia alma!",
  ui_story_5063_50631801_24_dialog_content = "¡Solo estás desafiando a tu padre por resentimiento! ¡Aún le temes más que a cualquier otra cosa!",
  ui_story_5063_50631801_25_dialog_content = "Admito que en el pasado tenía demasiado miedo para enfrentarme a él.",
  ui_story_5063_50631801_26_dialog_content = "Puede que no haya sido un buen padre... Pero sé que hizo lo mejor por mí.",
  ui_story_5063_50631801_27_dialog_content = "¡Por eso nunca podré perdonar las tradiciones que lo encarcelaron durante toda su vida!",
  ui_story_5063_50631801_28_dialog_content = "Si no fuera por ellos, podríamos haber sido más como Pam y su padre...",
  ui_story_5063_50631801_29_dialog_content = "¿Has perdido la cabeza? ¿De verdad sientes envidia de esos criminales?!",
  ui_story_5063_50631801_30_dialog_content = "¿Todavía recuerdas por qué querías convertirte en Juez Principal?",
  ui_story_5063_50631801_31_dialog_content = "¡Para tener éxito como mi padre y heredar su legado, por supuesto!",
  ui_story_5063_50631801_32_dialog_content = "Mi razón es diferente. Me convertí en Juez Principal para proteger a Lumopolis y su gente...",
  ui_story_5063_50631801_33_dialog_content = "¡Por eso nunca dejaré que lo hagas a tu manera!",
  ui_story_5063_50631801_34_dialog_content = "Ahora vete, ¡para que esta ciudad finalmente pueda liberarse de tu malicioso orgullo!",
  ui_story_5063_50631802_1_dialog_content = "No——",
  ui_story_5063_50631802_2_dialog_content = "¡Soy la hija ideal de papá, no tú! ¿¡Cómo podría perder contigo?!",
  ui_story_5063_50631802_3_dialog_content = "Porque tu visión de una \"hija ideal\" fue creada cuando aún no entendía a mi padre.",
  ui_story_5063_50631802_4_dialog_content = "Al ser dura e implacable con los demás y conmigo misma, y al juzgar casos estrictamente de acuerdo con la ley, pensé que podría convertirme en la hija que mi padre siempre quiso.",
  ui_story_5063_50631802_5_dialog_content = "Pero estaba equivocado. Después de revisar los casos antiguos de mi padre, descubrí que a pesar de su actitud fría y distante...",
  ui_story_5063_50631802_6_dialog_content = "Papá se esforzó por recopilar la mayor cantidad de pruebas posibles antes de ir a juicio, para poder entregar los veredictos más justos posibles.",
  ui_story_5063_50631802_7_dialog_content = "Sin embargo, su idea de \"justicia\" todavía estaba manchada por la arrogancia de las tradiciones anticuadas.",
  ui_story_5063_50631802_8_dialog_content = "Eso explicaría por qué todos dicen que mi padre fue el mejor Juez Principal en la historia de Lumopolis, y que nunca podré igualar su grandeza.",
  ui_story_5063_50631802_9_dialog_content = "...Nunca entendí verdaderamente a él ni su forma de pensar.",
  ui_story_5063_50631802_10_dialog_content = "Pero como jueces, siempre y cuando sigamos haciendo nuestro mejor esfuerzo, el estado de derecho eventualmente volverá a un equilibrio.",
  ui_story_5063_50631802_11_dialog_content = "Mi padre me ha dado dos oportunidades para vivir ahora. Aunque su sacrificio puede que no sea suficiente para restaurar el equilibrio entre nosotros...",
  ui_story_5063_50631802_12_dialog_content = "Estoy dispuesto a aceptar eso.",
  ui_story_5063_50631802_13_dialog_content = "Continuaré siguiendo los pasos de mi padre, corrigiendo sus errores mientras me esfuerzo por convertirme en un juez principal mucho más grande de lo que él jamás fue...",
  ui_story_5063_50631802_14_dialog_content = "Con mi vida, ¡equilibraré las balanzas de la justicia!",
  ui_story_5063_50631802_15_dialog_content = "...",
  ui_story_5063_50631802_16_dialog_content = "Creo que finalmente es hora de despertar.",
  ui_story_5063_50631802_17_dialog_content = "¡Noche Blanca en lo alto! Por la presente declaro——",
  ui_story_5063_50631802_18_dialog_content = "<size=45>¡Se suspende el juicio!</size>"
}
return config
